export default [{"id":353,"question":"رجلٌ تزوَّج امرأةً، وأنجبت منه، ثم طلَّقها وحرَّمها على نفسه مُتلفِّظًا بكلمة: \"هي عليه حرام، تحلّ للكلاب السود ولا تحلّ له\"، وبعد عشرين سنة حاول أحدُ أبنائها منه إقناعه بالزواج منها من جديدٍ بمُوجب عقدٍ، فهل عليه شيءٌ؟ علمًا بأنَّ له منها أبناء ومن غيرها.","title":"ما حكم من يقول لزوجته: أنت عليَّ حرام؟","answer":"الجواب: هذا لا يحتاج إلى نظر في الطلاق، لا بدّ أن ينظر في الطلاق الذي صدر منه، فإذا ثبت أن الطلاق واحدةٌ أو اثنتان فله الرجوع إليها بعقدٍ جديدٍ، وإذا ثبت أنه طلَّقها الطلقة الثالثة، وأنها الثالثة؛ فإنها لا تحلّ له حتى تنكح زوجًا غيره.\nفلا بد من النظر، لا ريب في ذلك، يتصل هو وهي ووليها بالعالم الذي يُفتيه، والقاضي الذي يُفتيه من أهل العلم، حتى يشرحوا جميعًا صفة الطلاق، الزوج والمطلقة ووليها يجتمعون عند الحاكم الشرعي أو عند العالم ليُفتيهم، حتى يشرحوا له الواقعة، وحتى يعرف الحقيقة، ثم تكون الفتوى على ضوء ذلك.\nوالقاعدة: أنه إذا كان الطلاقُ واحدةً أو اثنتين فإنها لا تحرمها، بل تجوز له بعقدٍ جديدٍ إذا كانت قد خرجت من العدَّة، أما إذا طلَّقها الطلقة الأخيرة الثالثة فإنها لا تحلّ له عند جميع المسلمين حتى تنكح زوجًا غيره؛ لقوله سبحانه: فَإِنْ طَلَّقَهَا يعني: الثالثة فَلَا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ [البقرة:230].\nأما التحريم فله شأنٌ آخر، إذا حرَّمها فتحريمه له شأنٌ آخر: إذا قال: \"هي عليه حرام\" أو \"كظهر أمه\" ولم يُطلقها، إنما حرمها؛ فهذا له كفَّارة، حرمها فقط ولم يُطلق، فإنَّ عليه كفَّارة قبل أن يمسَّها، وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا قبل أن يمسَّها.","link":"https://binbaz.org.sa/fatwas/4545/ما-حكم-من-يقول-لزوجته-انت-علي-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0406.mp3","categories":["الطلاق","الأيمان والنذور","الظهار"]},{"id":551,"question":"إذا قال: \"أنت عليّ حرام\" يُنظر في نيته؟","title":"حكم من قال لامرأته: \"أنت عليّ حرام\"","answer":"الجواب: لا، إذا قال: \"أنتِ علي حرام\"؛ فحكمه حكم الظهار، إلا إذا عَلّق.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6382/حكم-من-قال-لامراته-انت-علي-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/maram117 - 02 - .mp3","categories":["الطلاق","الأيمان والنذور","الظهار"]},{"id":554,"question":"إذا قال: إذا خرجت وإذا فعلت ِ كذا فأنتِ عليّ حرام، فهل يُسأل عن نيته؟","title":"ما معنى وحكم الطلاق المُعَلّق؟","answer":"الجواب: هل قصده تحريمها أو منعها بس؟ أما إذا كان قصده منعها فهذا عليه كفارة يمين، وإذا كان قصده تحريمها فحكمه الظهار.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6385/ما-معنى-وحكم-الطلاق-المعلق","audio":"https://files.zadapps.info/binbaz.org.sa/maram120.mp3","categories":["الأيمان والنذور","الطلاق","الظهار"]},{"id":1853,"question":"هل كفارة الظهار تسقط بطلاق الزوجة؟","title":"هل تسقط كفارة الظهار بطلاق الزوجة؟","answer":"الجواب:\nكفارة الظهار ما تجب عليه إلا إذا كان يُجامعها، وإذا طلَّقها ما عنده كفارة ظهار، لكن لو عادت إليه لا يطأها حتى يُكفِّر.","link":"https://binbaz.org.sa/fatwas/21962/هل-تسقط-كفارة-الظهار-بطلاق-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طلاق الزوجة هل يسقط كفارة الظهار.mp3","categories":["الطلاق","الظهار"]},{"id":4289,"question":"الرجل إذا قال لزوجته هي عليه حرام بنية الطلاق يكون طلاقًا؟","title":"حكم من قال لزوجته هي عليه حرام بنية الطلاق","answer":"الجواب: لا - يكون ظهارًا .","link":"https://binbaz.org.sa/fatwas/24561/حكم-من-قال-لزوجته-هي-عليه-حرام-بنية-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقع الطلاق إذا قال لزوجته هي عليه حرام بنية الطلاق.mp3","categories":["الطلاق","الأيمان والنذور","الظهار"]},{"id":6196,"question":"وكذلك سؤال آخر: غضب رجل من زوجته، فأقسم عليها يمينًا بالحرام منها أن لا يطأها مدة سنة كاملة، فما تحليل هذا الحلف؟ وما كفارته؟","title":"حكم من أقسم بالحرام أن لا يطأ زوجته سنة كاملة","answer":"الجواب: إذا حلف أن لا يطأها؛ فعليه كفارة يمين، إذا قال: عليه الحرام أنه لا يطأها شهرًا، أو سنة، أو يومًا، أو سنتين، أو أكثر؛ فهذا حكمه حكم اليمين. أما إذا قال: هي حرام علي، وجعلها كظهر أمه، أو كظهر أخته؛ فهذا حكمه حكم الظهار، تحرم عليه حتى يعتق رقبة، فإن لم يجد؛ صام شهرين متتابعين، فإن عجز؛ أطعم ستين مسكينًا. أما إذا قال: عليه الحرام ما يطأها، أو عليه حرام ما يكلمها، أو عليه حرام ما ينام معها، فهذا حكمه حكم اليمين.","link":"https://binbaz.org.sa/fatwas/1660/حكم-من-اقسم-بالحرام-ان-لا-يطا-زوجته-سنة-كاملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_540.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":6230,"question":"وآخر يقول: أنا متزوج من امرأتين، وفي لحظة غضب قلت : حريمي علي كحرمة أمي، وأريد الآن أن أعرف هل يحرمن جميعًا، أم علي كفارة ؟","title":"حكم الظهار من الزوجتين بلفظ واحد","answer":"الجواب:  ما كان ينبغي عليه أن يحرم زوجاته، ينبغي له إذا أحس بالغضب أن يتعوذ بالله من الشيطان الرجيم، وهكذا ينبغي، ولا يعجل في الأمور. والظهار، والتحريم للزوجات محرم، ومنكر من القول، وزروًا؛ كما سماه الله في الآية، لكن إذا وقع منك ذلك قلت: حريمي مثل أمي، أو مثل ظهر أمي، أو مثل أختي، أو ظهر أختي، فهذا يسمى الظهار. فعليك عتق رقبة مؤمنة، وإن عجزت؛ تصوم شهرين متتابعين، وإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا، أو تعشيهم، أو تغديهم قبل أن تقربها، قبل أن تمسها، فهذه هي الكفارة من الظهار، إن عجز عن العتق، والصيام يطعم ستين مسكينًا، يعشيهم، أو يغديهم مجتمعين، أو متفرقين، أو يعطيهم على نصف الصاع تمرًا، أو رزًا، كيلو ونصف تقريبًا لكل واحد قبل أن يمس زوجته التي حرمها، وإذا قال: جميعًا حريمي بكلمة واحدة، أو نسائي، أو زوجاتي عليه مثل أمي، أو حرام مثل أمي؛ كفى كفارة واحدة؛ لأنها كلمة واحدة. السؤال: ما ينفع فلوس؟ الجواب:  لا فلوس لا، طعام.","link":"https://binbaz.org.sa/fatwas/1750/حكم-الظهار-من-الزوجتين-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_589.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6235,"question":"وآخر يقول: أنا متزوج من امرأتين، وفي لحظة غضب قلت : حريمي علي كحرمة أمي، وأريد الآن أن أعرف هل يحرمن جميعًا، أم علي كفارة ؟","title":"حكم الظهار من الزوجتين بلفظ واحد","answer":"الجواب:  ما كان ينبغي عليه أن يحرم زوجاته، ينبغي له إذا أحس بالغضب أن يتعوذ بالله من الشيطان الرجيم، وهكذا ينبغي، ولا يعجل في الأمور. والظهار، والتحريم للزوجات محرم، ومنكر من القول، وزروًا؛ كما سماه الله في الآية، لكن إذا وقع منك ذلك قلت: حريمي مثل أمي، أو مثل ظهر أمي، أو مثل أختي، أو ظهر أختي، فهذا يسمى الظهار. فعليك عتق رقبة مؤمنة، وإن عجزت؛ تصوم شهرين متتابعين، وإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا، أو تعشيهم، أو تغديهم قبل أن تقربها، قبل أن تمسها، فهذه هي الكفارة من الظهار، إن عجز عن العتق، والصيام يطعم ستين مسكينًا، يعشيهم، أو يغديهم مجتمعين، أو متفرقين، أو يعطيهم على نصف الصاع تمرًا، أو رزًا، كيلو ونصف تقريبًا لكل واحد قبل أن يمس زوجته التي حرمها، وإذا قال: جميعًا حريمي بكلمة واحدة، أو نسائي، أو زوجاتي عليه مثل أمي، أو حرام مثل أمي؛ كفى كفارة واحدة؛ لأنها كلمة واحدة. السؤال: ما ينفع فلوس؟ الجواب:  لا فلوس لا، طعام.","link":"https://binbaz.org.sa/fatwas/1750/حكم-الظهار-من-الزوجتين-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_589.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6246,"question":"وآخر يقول: أنا متزوج من امرأتين، وفي لحظة غضب قلت : حريمي علي كحرمة أمي، وأريد الآن أن أعرف هل يحرمن جميعًا، أم علي كفارة ؟","title":"حكم الظهار من الزوجتين بلفظ واحد","answer":"الجواب:  ما كان ينبغي عليه أن يحرم زوجاته، ينبغي له إذا أحس بالغضب أن يتعوذ بالله من الشيطان الرجيم، وهكذا ينبغي، ولا يعجل في الأمور. والظهار، والتحريم للزوجات محرم، ومنكر من القول، وزروًا؛ كما سماه الله في الآية، لكن إذا وقع منك ذلك قلت: حريمي مثل أمي، أو مثل ظهر أمي، أو مثل أختي، أو ظهر أختي، فهذا يسمى الظهار. فعليك عتق رقبة مؤمنة، وإن عجزت؛ تصوم شهرين متتابعين، وإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا، أو تعشيهم، أو تغديهم قبل أن تقربها، قبل أن تمسها، فهذه هي الكفارة من الظهار، إن عجز عن العتق، والصيام يطعم ستين مسكينًا، يعشيهم، أو يغديهم مجتمعين، أو متفرقين، أو يعطيهم على نصف الصاع تمرًا، أو رزًا، كيلو ونصف تقريبًا لكل واحد قبل أن يمس زوجته التي حرمها، وإذا قال: جميعًا حريمي بكلمة واحدة، أو نسائي، أو زوجاتي عليه مثل أمي، أو حرام مثل أمي؛ كفى كفارة واحدة؛ لأنها كلمة واحدة. السؤال: ما ينفع فلوس؟ الجواب:  لا فلوس لا، طعام.","link":"https://binbaz.org.sa/fatwas/1750/حكم-الظهار-من-الزوجتين-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_589.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6303,"question":"رجل طلق زوجته دون براءة، طلقها ثاني مرة دون براءة، ثم أرجعها، ومن ثم حرمها مرة أخرى على نفسه مثل أمه، أو أخته، وهو رجل  مقطوع، عمره خمس وستون عامًا، وهو لاجئ، ليس له أحد من الأهل، فما حكم ذلك؟","title":"رجل طلق زوجته مرتين ثم ظاهرها","answer":"الجواب: عليه التوبة إلى الله، وعليه كفارة الظهار، هذا مضى عليه طلقتان، وبقي عليه طلقة واحدة، فعليه أن يكفر كفارة الظهار، مثل ما أمر الله بذلك، وهي: عتق رقبة مؤمنة، فإن لم يستطع؛ صام شهرين متتابعين قبل أن يمسها، فإن لم يستطع؛  أطعم ستين مسكينًا، ستين فقيرًا، ثلاثين صاعًا، كل واحد له نصف صاع، تمر، أو رز من قوت البلد، رز، أو حنطة، أو شعير يعطيه الفقراء، ستين فقيرًا، ثلاثون صاعًا، كل واحد له نصف صاع قبل أن يمسها.","link":"https://binbaz.org.sa/fatwas/1891/رجل-طلق-زوجته-مرتين-ثم-ظاهرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_674.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6317,"question":"رجل طلق زوجته دون براءة، طلقها ثاني مرة دون براءة، ثم أرجعها، ومن ثم حرمها مرة أخرى على نفسه مثل أمه، أو أخته، وهو رجل  مقطوع، عمره خمس وستون عامًا، وهو لاجئ، ليس له أحد من الأهل، فما حكم ذلك؟","title":"رجل طلق زوجته مرتين ثم ظاهرها","answer":"الجواب: عليه التوبة إلى الله، وعليه كفارة الظهار، هذا مضى عليه طلقتان، وبقي عليه طلقة واحدة، فعليه أن يكفر كفارة الظهار، مثل ما أمر الله بذلك، وهي: عتق رقبة مؤمنة، فإن لم يستطع؛ صام شهرين متتابعين قبل أن يمسها، فإن لم يستطع؛  أطعم ستين مسكينًا، ستين فقيرًا، ثلاثين صاعًا، كل واحد له نصف صاع، تمر، أو رز من قوت البلد، رز، أو حنطة، أو شعير يعطيه الفقراء، ستين فقيرًا، ثلاثون صاعًا، كل واحد له نصف صاع قبل أن يمسها.","link":"https://binbaz.org.sa/fatwas/1891/رجل-طلق-زوجته-مرتين-ثم-ظاهرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_674.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6424,"question":"قال في سبل السلام: لو ظاهر الرجل يريد طلاقًا؛ كان ظهارًا، ولو طلق يريد ظهارًا؛ كان طلاقًا، فهل هذا صحيح؟ وكيف يجمع بينه، وبين إنما الأعمال بالنيات؟","title":"حكم اعتبار الظهار طلاقاً","answer":"الجواب: الله جعل الظهار ظهارًا؛ لأن الجاهلية تجعله طلاقًا، فالله حكم بأن الظهار ظهار تحريم، وبين فيه الكفارة  في كتابه الكريم، فلا يجعل الطلاق، فإذا قال: أنت علي كظهر أمي، أو كظهر أختي، أو بنتي؛ فإنه ظهار، ولو نواه طلاقًا، بل هو ظهار كما شرع الله ضد أعمال الجاهلية، قد أبطل الله أعمال الجاهلية؛ فيكون له حكم الظهار، وعليه الكفارة، وهي: عتق رقبة، فإن عجز؛ صام شهرين متتابعين، فإن عجز؛ أطعم ستين مسكينًا قبل أن يمسها. أما إذا قال: أنت طالق، ونوى الظهار، ما يصير ظهارًا؛ لأن هذا ما يرد على الظهار، أنت طالق لفظه صريح الطلاق، فلا ينتقل عن صريح الطلاق إلى معنى آخر.","link":"https://binbaz.org.sa/fatwas/2128/حكم-اعتبار-الظهار-طلاقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_776.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":7149,"question":"قوله: أنت علي حرام كحرمة البنت على أبيها، أرجو من سماحتكم إفادتي ماذا يلزمني في هذا، وما هي كفارة هذا اليمين، جزاكم الله خيراً؟","title":"حكم قول أنت علي حرام","answer":"الجواب:\n\nبسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\n\nفهذه العبارة وأشباهها على الصحيح من أقوال أهل العلم تعتبر ظهارًا، لها حكم الظهار الذي بينه الله في كتابه العظيم في سورة المجادلة، فإذا قال لزوجته أنت علي حرام كبنتي، أو أختي، أو أنت علي حرام، وأطلق، فهذا حكمه حكم الظهار؛ فعليه التوبة إلى الله من ذلك؛ لأن هذا منكر وزور، ما هي عليه حرام، الله أحلها له بالعقد الشرعي.\n\nفقوله إنها عليه حرام غلط منه، ولا يجوز له ذلك، ومنكر، فالواجب عليه التوبة من ذلك، ولهذا يقول سبحانه: وَإِنَّهُمْ لَيَقُولُونَ مُنْكَرًا مِنَ الْقَوْلِ وَزُورًا [المجادلة:2] وعليه الكفارة التي بينها الله في كتابه العظيم، وهي عتق رقبة مؤمنة، فإن عجز؛ صام شهرين متتابعين، ستين يومًا، فإن عجز؛ أطعم ستين مسكينا لكل مسكين، نصف صاع من قوت البلد، من تمر أو أرز أو بر أو غير ذلك، وإن أطعم أكثر من ذلك؛ فلا بأس.\n\nالمقصود: أنه لا بد أن يطعم ستين مسكينًا، يعشيهم، أو يغديهم، أو يعطيهم نصف صاع من قوت البلد، وإذا كان معه إدام؛ كان أفضل، وهذا كله على الترتيب، هذا على الترتيب ليس على التخيير. \n\nأولًا: العتق إذا تيسر، فإن لم يتيسر؛ فالصيام، فإن عجز عن ذلك لأسباب تقتضي ذلك؛ انتقل إلى الإطعام قبل أن يمسها، لا يقربها لا بقبلة ولا بجماع، لا يستمتع بها بشيء حتى يؤدي هذه الكفارة مع التوبة الصادقة النصوح إلى الله سبحانه من هذا العمل؛ لأن الله قال: مِنْ قَبْلِ أَنْ يَتَمَاسَّا [المجادلة:3].\n\nالسؤال: ولا يغني قيمة المال عن الإطعام؟\n\nالجواب: ولا يغني القيمة لا. الواجب العتق، ثم الصيام، ثم الإطعام.","link":"https://binbaz.org.sa/fatwas/3188/حكم-قول-انت-علي-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1546.mp3","categories":["الظهار","الأخلاق المذمومة"]},{"id":8246,"question":"الرسالة التالية وصلت إلى البرنامج من العراق، وباعثتها إحدى الأخوات من هناك تقول: إن هناك رجلاً حصل بينه وبين زوجته شيء من الشجار، وتلفظت بلفظ غريب وقالت: أنت كأبي علي، وبعد حين حضرت إليه تستعفيه على ما حدث، فماذا ينصحها سماحة الشيخ؟ وماذا يكون موقف الزوج والحالة هذه؟","title":"حكم ظهار الزوجة من زوجها","answer":"الجواب: أولاً: عليها أن تستغفر الله هي؛ لأنه ليس لها أن تحرم زوجها لا كأبيها ولا كأمها ولا غير ذلك، فعليها أن تستغفر الله ؛ لأنه ليس للمسلم أن يحرم ما أحل الله له، قال الله عز وجل يخاطب نبيه محمداً عليه الصلاة والسلام: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ [التحريم:1] الآية.\nفعليها التوبة والاستغفار، وعليها كفارة اليمين؛ لأنها ليس لها ظهار هي، الظهار من الزوج على الزوجة، أما الزوجة فإذا حرمت زوجها فعليها كفارة يمين كسائر ما يحرم من متاع الدنيا؛ كما لو حرمت طعام فلان، أو دخول بيت فلان، أو كلام فلان أو ما أشبه ذلك فعليها كفارة يمين، وهي: إطعام عشرة مساكين، لكل مسكين نصف صاع من قوت البلد من تمر أو أرز أو غيرهما، ومقداره كيلو ونصف تقريباً، أو كسوتهم؛ كسوة العشرة بما يجزئهم في الصلاة أو عتق رقبة كما نص الله عليه في كتابه العزيز في سورة المائدة، ومن عجز عن هذه الثلاثة لفقره صام ثلاثة أيام وأجزأته، والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/6044/حكم-ظهار-الزوجة-من-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09704.mp3","categories":["الظهار"]},{"id":8773,"question":"هذه رسالة وردتنا من السائل أحمد سيد حزين من جمهورية مصر العربية ومقيم بالعراق يقول: أقسمت على زوجتي طلاق بالثلاث بأن تخرج من منزلي وتكون علي حرام كأمي وأختي مع سبق النية بأن أطلقها، وفعلاً خرجت من المنزل وذهبت إلى أهلها، وبعد فترة من الزمن عادت إلى المنزل بواسطة الأهل وبدون علمي وإلى الآن لم أعاشرها معاشرة الأزواج، أفيدوني أفادكم الله؟","title":"حكم من طلق بالثلاث وظاهر في نفس الوقت","answer":"الجواب: ما دمت قصدت بهذا طلاقها وفراقها فإن هذا الطلاق يقع به واحدة، إذا كان بهذا اللفظ الذي قلته، قلت: طالق بالثلاث يقع به واحدة على الصحيح من أقوال العلماء، ولك الرجوع إليها ما دامت في العدة، تقول: راجعت زوجتي فلانة ويكفي هذا، والسنة أن يكون بحضرة شاهدين، تقول هذا الكلام بحضرة شاهدين من أخيار المسلمين، تقول: راجعت زوجتي فلانة ويكفي، إذا كنت ما طلقتها قبل هذا طلقتين.. إذا كان ما سبق منك شيء قبل هذا من طلاق مرتين، فإن هذا يكون واحدة، فإن كان سبق منك واحدة قبل هذا يكون هذه ثانية ولك المراجعة، فإن كان سبق منك طلقتان فهذه تكون الثالثة ولا رجعة ما دمت أردت بهذا طلاقها وفراقها بالكلية وإخراجها من بيتك مطلقة، ومتى رجعت إليك لأن هذا الطلاق ما قبله طلقتان فإن عليك أيضاً كفارة الظهار؛ لأنك حرمتها أيضاً، فعليك مع ذلك كفارة الظهار قبل أن تقربها قبل أن تمسها، وكفارة الظهار هي: عتق أمة أو عبد إذا تيسر ذلك لوجه الله، فإن لم تستطع ذلك تصوم شهرين متتابعين عن هذا الظهار، فإن لم تقدر على ذلك لظروفك فعليك أن تطعم ستين مسكيناً، عليك عند العجز عن الصيام إطعام ستين مسكيناً، أي: ستين فقير من فقراء المسلمين تعطيهم ثلاثين صاع كل صاع بين اثنين، والصاع أربع حفنات باليدين الممتلأتين المعتدلتين كل حفنة مد، والأربع صاع بصاع النبي عليه الصلاة والسلام ملء اليدين المعتدلتين المملوءتين وهو معروف، أو تكسوهم كسوة كل واحد يعطى قميص أو إزار ورداء، أو تعتق عبد أو عبدة، لكن تقدم إذا عجزت عن..، المقصود في هذا ما فيه إلا الإطعام ما فيه كسوة الكسوة هذا في كفارة اليمين، المقصود عليك في هذا إطعام ستين مسكين كل مسكين له نصف الصاع فقط، ومقداره بالوزن كيلو ونصف تقريباً من قوت البلد من تمر أو أرز أو حنطة أو ذرة إن كانت قوت البلد أو شعير إن كانت كان قوت البلد يكفي هذا، قبل أن تمسها قبل أن تقربها إذا عجزت عن الصيام وعن العتق، هذا عن الظهار، أما الطلاق فعرفت أن عليك أنه يقع طلقة واحدة ولك مراجعتها في حال عدتها، فإن كانت قد خرجت من العدة فلا بد من نكاح جديد بالشروط المعتبرة شرعاً. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6925/حكم-من-طلق-بالثلاث-وظاهر-في-نفس-الوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_218/21807.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":8906,"question":"نعود في بداية هذا اللقاء إلى رسالة الأخ آدم محمد عثمان، السوداني والمقيم بالعراق، أخونا يسأل في هذه الحلقة ويقول: يوجد بعض من الناس عندما يطلق زوجته يقول: أنت في مكان والدتي، فما حكمه إذا أرجعها، وهل يحق له رجوعها أو لا؟","title":"حكم من قال لزوجته عند تطليقها: (أنت في مكان والدتي)","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإذا كان الطلاق رجعيًا، إن كان طلقها طلقة واحدة أو طلقتين فله مراجعتها ما دامت في العدة، فإذا خرجت من العدة قبل أن يراجعها جاز له أن يعود إليها بنكاح جديد بالشروط المعتبرة شرعًا من الولي والشاهدين، والرضا كما هو معلوم.\nأما قوله: أنت في مكان والدتي، بعدما طلقها، هذا يرجع إلى نيته، إن كان قصده من ذلك: أنها عنده عزيزة، وكريمة وأنه يقدرها، هذا ليس بشيء ولا حرج فيه وليس من الظهار في شيء، يعني: عبارة موهمة.\nأما إن كان قصده (أنت في مكان والدتي)، يعني: أنت محرمة علي، وأنت علي حرام كوالدتي، فهذا يسمى الظهار، ولا تحل له إذا كان الطلاق رجعيًا إلا بعد الكفارة، لا يمسها ولو راجعها، يراجعها لا بأس أو يعقد عليها إذا كانت قد خرجت من العدة، لا بأس، لكن لا يمسها حتى يكفر كفارة الظهار وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا ثلاثين صاعًا، كل صاع يقسم بين اثنين، كل واحد له نصف الصاع من التمر، من الرز، من الحنطة، من قوت البلد، هذا هو الواجب، وليس له أن يمسها حتى يخرج هذه الكفارة، بعدما يراجعها أو بعدما يعقد عليها ليس له أن يمسها يعني: ليس له أن يجامعها إلا بعدما يخرج هذه الكفارة.\nأولًا: رقبة -عتق رقبة مؤمنة- إن قدر.\nثانيًا: صيام شهرين متتابعين، إذا عجز عن الرقبة.\nثالثًا: أن يطعم ستين مسكينًا ثلاثين صاعًا من قوت البلد، إذا عجز عن الصيام، ثم بعد هذا له أن يباشرها.\nأما إن كان الطلاق كاملًا، طلقها الطلقة الأخيرة -الثالثة- فهذه لا تحل له حتى تنكح زوجًا غيره، حتى تنكح زوجًا آخر نكاحًا شرعيًا لا نكاح تحليل، وحتى يطأها أيضًا الزوج الثاني، فإذا طلقها الطلقة الأخيرة-الثالثة- فإنها تحرم عليه تحريمًا مؤقتًا مادامت لم تتزوج، فإذا تزوجت زواجًا شرعي ووطئها الزوج الجديد ثم طلقها أو مات عنها فإنها تحل للأول، إذا كان النكاح شرعي مو بنكاح تحليل، أما نكاحها للتحليل ليحللها للأول هذا نكاح باطل لا يجوز، لكن إذا تزوجها الزوج الجديد بنية الرغبة فيها لكن لم يقدر الله له الرغبة بل طلقها بعد الدخول بها، أي: بعد أن جامعها أو مات عنها، فإنها تحل للأول بعقد جديد، ........... جديد بشروطه المعتبرة شرعًا.\nوإذا كان قال لها بعدما طلقها الطلقة الأخيرة: أنت في مكان أمي، فهذا لا يؤثر شيء، ولو كان أراد التحريم، لأنها صارت أجنبية، صارت أجنبية ما يكون تحريمها تحريم الظهار، إذا كانت بعد الطلقة الأخيرة، قال: أنت في مكان أمي، قصده تحريمها، قصده أن ينوي هذا تحريمها، أو قال: أنت كظهر أمي، أو أنت محرمة علي، فإنه لا يلحقها هذا كالزوجة، ولكن يجب فيه كفارة يمين، مثل: تحريم الطعام والشراب ونحو ذلك، لأنها صارت أجنبية بعد الطلقة الأخيرة، فإذا قال لها: أنت محرمة علي، أو أنت علي كظهر أمي، بعد الطلاق الأخير، فإنها تكون في حكم تحريم الطعام واللباس والشراب، يعني: يستحلها بكفارة اليمين، كفارة يمين ويكفي، إطعام عشرة مساكين أو كسوتهم، ولا يكون ظهارًا؛ لأن الظهار إنما يكون مع النساء مع الزوجات، كما قال تعالى: وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ [المجادلة:3] هي بعد الطلقة الأخيرة ما عاد صارت من النساء، صارت أجنبية، فيكون تحريمه لها مثل تحريم الثياب والطعام ونحو ذلك والجواري فيه كفارة اليمين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7062/حكم-من-قال-لزوجته-عند-تطليقها-انت-في-مكان-والدتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_169/16901.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":9178,"question":"سماحة الشيخ إذا أذنتم لي أسأل بعض الأسئلة: هل يلزم المطلق أن يشهد أحدًا على طلاقه وعلى رجعته، أو يبقى ذلك بينه وبين زوجته وبين نفسه؟","title":"حكم الإشهاد على الطلاق والرجعة","answer":"الجواب: السنة أن يشهد، لقوله تعالى: وَأَشْهِدُوا ذَوَي عَدْلٍ مِنْكُمْ وَأَقِيمُوا الشَّهَادَةَ لِلَّهِ [الطلاق:2] فالسنة أن يشهد شاهدين؛ لأن الله جل وعلا قال في سورة الطلاق: وَأَشْهِدُوا ذَوَي عَدْلٍ مِنْكُمْ [الطلاق:2] قال بعض أهل العلم: المراد به الطلاق، وقال بعضهم: المراد به الرجعة، ولا مانع من كون الآية في الأمرين جميعًا فيشهد على طلاقها ويشهد على رجعتها، فإذا طلق أشهد حتى لا ينكر ذلك؛ فإن الشيطان قد يزين له الإنكار، فإذا أشهد كان هذا من أسباب السلامة والعافية من طاعة الشيطان في إنكار الطلاق، وهكذا الرجعة، عليه أن يشهد على رجعتها؛ لأنه قد يتأخر في إبلاغ الزوجة فيكون الشهود بينة له تعينه على حصول المطلوب من الرجعة.\nفالمقصود أنه يشهد على الطلاق والرجعة هذا هو المشروع. نعم.\nالمقدم: ومن لم يفعل هذا فعليه أن ...\nالشيخ: الطلاق واقع، والرجعة صحيحة إذا راجعها في العدة وأخبرها بذلك ولو لم يشهد صحت الرجعة؛ لأن الله قال: وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَلِكَ إِنْ أَرَادُوا إِصْلاحًا [البقرة:228]، ولم يقل بشرط كذا وكذا. نعم.\nالمقدم: طيب لكن عليه أن يتدارك الكتابة أو ليس عليه ذلك؟\nالشيخ: لا يلزمه فيما يظهر لكن لو فعل امتثالًا للأمر واحتياطًا حسن. نعم.","link":"https://binbaz.org.sa/fatwas/7338/حكم-الاشهاد-على-الطلاق-والرجعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_180/18002.mp3","categories":["الطلاق","الظهار","الرجعة"]},{"id":9332,"question":"أحد الإخوة سوداني أيضاً بعث يسأل ويقول: رجل قال لزوجته: أنت مثل أختي وهو لا يقصد في ذلك عدم المعاشرة الزوجية، هل يخرج بدل الإطعام نقداً أم لا، نرجو أن تفيدونا هذا جزاكم الله خيراً؟","title":"حكم من قال لزوجته: أنت مثل أختي دون قصد تحريمها","answer":"الجواب: هذا يختلف بحسب نيته، إن كان قال لزوجته: أنت مثل أختي أو مثل أمي من باب الاحترام، من باب الإكرام، من باب يعني: التقدير لها فهذا ليس بحرام وليس عليه شيء، لكن ترك هذا أولى ينبغي تركه؛ لأنه يوهم، ينبغي أن لا يستعمل هذا معها.\nأما إن كان أراد تحريمها، يعني: أنها محرمة مثل أخته، أو أنها محرمة كأمه، أو كبنته هذا هو الظهار المعروف وعليه كفارة الظهار وهي مرتبة بنص القرآن.\nأولاً: عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا، ما فيها نقود، ستين مسكين طعام يعشيهم أو يغديهم أو يدفع لهم طعامًا نيئًا نصف صاع لكل واحد ثلاثين صاعاً من الحنطة، من البر، من الشعير، من قوت البلد من التمر، ويكفي ذلك حتى يمسها بعد ذلك، يعني: لا يمسها حتى يدفع عليه الكفارة، أما النقود فلا تصلح. نعم.\nالمقدم: النقد في هذا لا يصلح؟\nالشيخ: لا يصلح لا، خلاف النص. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7486/حكم-من-قال-لزوجته-انت-مثل-اختي-دون-قصد-تحريمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_155/15506.mp3","categories":["الطلاق","الظهار"]},{"id":9404,"question":"مع مطلع هذه الحلقة نعود إلى رسالة إحدى الأخوات المستمعات من العراق تقول (خ. م. ص) أختنا عرضنا سؤالًا من رسالتها في حلقة مضت.وفي هذه الحلقة تسأل وتقول: إذا حرمت المرأة نفسها على زوجها فما الحكم؟","title":"حكم تحريم المرأة نفسها على زوجها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والعاقبة للمتقين، والصلاة والسلام على عبده ورسوله وخليله، وأمينه على وحيه، نبينا وإمامنا وسيدنا محمد بن عبد الله وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فإن التحريم لما أحل الله أمر لا يجوز، فليس للمرأة أن تحرم زوجها، وليس للرجل أن يحرم زوجته، وليس لأحد من الناس أن يحرم ما أحل الله، فلا يقول: اللحم علي حرام، أو اللبن علي حرام، أو الفاكهة علي حرام، أو الحبوب علي حرام، أو غير هذا مما أحل الله، يقول الله : يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ [التحريم:1] وقال سبحانه في الذين يظاهرون نسائهم، يعني: يحرمون نساءهم: وَإِنَّهُمْ لَيَقُولُونَ مُنْكَرًا مِنَ الْقَوْلِ وَزُورًا [المجادلة:2].\nفليس للمؤمن ولا لمؤمنة تحريم ما أحل الله، فالرجل إذا حرم زوجته وظاهر منها يكون عليه الكفارة وهي عتق رقبة مؤمنة، فإن لم يجد صام شهرين متتابعين، فإن لم يستطع أطعم ستين مسكينًا ثلاثين صاعًا لكل مسكين نصف صاع من قوت البلد من تمر أو غيره، وليس له أن يقربها حتى يؤدي الكفارة كما نص عليه كتاب الله في سورة المجادلة.\nأما المرأة فليس لها حكم الظهار، وإنما هو للرجل؛ لأن الله قال: وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ [المجادلة:3].\nأما المرأة إذا حرمت زوجها بأن قالت: أنت علي كظهر أبي، أو أنت علي حرام، أو أنا محرمة عليك أو ما أشبه ذلك، فإنها بهذا قد غلطت وأخطأت وعليها التوبة والاستغفار؛ لأنها حرمت ما أحل الله لها، وعليها كفارة يمين فقط؛ لقول الله جل وعلا: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:1-2] فسمى تحريمه ﷺ للعسل كما في الرواية المشهورة أو لـمارية الجارية سماه يمينًا.\nوهكذا الرجل إذا حرم طعامًا أو شرابًا أو فاكهة أو امرأة ليست زوجة له فإن عليه كفارة يمين، وهكذا المرأة إذا حرمت زوجها أو حرمت فاكهة أو كلام فلان أو زيارة فلان يكون عليه كفارة يمين، وليس عليها ظهار، الظهار للزوج خاصة، أما هي فعليها كفارة اليمين وهي إطعام عشرة مساكين أو كسوتهم أو تحرير رقبة، فإن عجزت، يعني: صارت فقيرة فإنها تصوم ثلاثة أيام، هكذا بين الله سبحانه في قوله جل وعلا: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] الآية.\nفبين  أن الواجب حفظ اليمين، وأن من عقد اليمين ثم حنث عليه الكفارة، والله قال سبحانه في قصة نبيه ﷺ لما حرم العسل: قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:2] فالتحريم لما أحل الله حكمه حكم اليمين.\nقال ابن عباس في هذا: «هو يمين يكفرها». نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7569/حكم-تحريم-المراة-نفسها-على-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_189/18901.mp3","categories":["الطلاق","الظهار"]},{"id":9449,"question":"يسأل أيضاً ويقول: حلفت فقلت: علي الحرام عن الحرمة، فهل هذا يمين أو أنه طلاق؟ وهل له كفارة أم لا أفيدوني أفادكم الله؟","title":"حكم تحريم الزوجة","answer":"الجواب: هذا القول حكمه حكم الظهار، إذا قال: عليه الحرام من زوجتي، أو علي الحرام من زوجتي، أو زوجتي محرمة علي أو كأمي أو كأختي أو كبنتي، وما أشبه هذه الألفاظ، فهذا حكمه حكم الظهار في أصح أقوال أهل العلم، وعليه كفارة الظهار، إذا كان لم ينو بها الطلاق، إنما نوى التحريم أو أطلقها ولم ينو شيئاً، فهذا فيه كفارة الظهار المنصوص عليها في سورة المجادلة، وهي عتق رقبة مؤمنة، فإن لم يتيسر صام شهرين متتابعين، فإن لم يستطع أطعم ستين مسكيناً قبل أن يمسها، قبل أن يقربها، هذا هو الواجب في الظهار، فإذا قال: زوجته عليه حرام، أو علي الحرام من زوجتي، أو محرمة زوجتي، أو حرام علي كأمي، أو كظهر أمي، أو كأختي أو كظهر أختي، أو ما أشبه هذه الألفاظ، فإن هذا يسمى: ظهاراً وعليه كفارته، وهو محرم لا يجوز هذا الكلام، سماه الله منكراً من القول وزور، فهي ليست حراماً عليه، فتحريمه لها منكر، فعليه التوبة إلى الله من ذلك، والاستغفار والندم، وعلى من فعل هذا الكفارة، وهي كما تقدم عتق عبد أو عبدة من أهل الإسلام، فإن لم يتيسر ذلك صام شهرين متتابعين، ستين يوماً، فإن لم يتيسر ذلك ولم يستطع أطعم ستين مسكيناً، يعني: ستين فقير لكل مسكين نصف صاع من قوت البلد، من تمر أو أرز أو حنطة أو غير هذا من قوت البلد، قبل أن يمسها قبل أن يقربها.\nأما لو قال: عليه الحرام إن فعل كذا، أو عليه الحرام إن كلم فلاناً، أو عليه الحرام ما يسافر إلى كذا وكذا، هذا تحريم معلق، إذا كان قصد منه منع نفسه من العمل الذي أراد وهو السفر أو الكلام، هذا يكون له حكم اليمين لا يكون له حكم الظهار في أصح أقوال أهل العلم، فإذا قال الزوج: علي الحرام ما أسافر اليوم، علي الحرام ما أكلم فلان، علي الحرام ما أزور فلان، علي الحرام ما تروحين إلى فلانة يبي يمنعها، علي الحرام ما تروحين لأهلك اليوم، لقصد منعها، أو منع نفسه من السفر أو ما أشبه ذلك، فهذه ألفاظ لها حكم اليمين في أصح أقوال أهل العلم، وعليه كفارة اليمين وهي إطعام عشرة مساكين، أو كسوتهم أو عتق رقبة، فمن عجز عن ذلك صام ثلاثة أيام، هذا هو الواجب في هذه المسائل، أما إن كان أراد الطلاق فله حكم آخر، إن كان أراد الطلاق ولم يرد التحريم، بل أراد طلاقها قال: علي حرام فلانة، أو زوجتي علي حرام وقصده طلاقها يكون طلقة واحدة، يكون هذا طلقة واحدة تحسب عليه، فإن كان قد طلقها قبلها طلقتين تمت الثلاث وحرمت عليه، حتى تنكح زوجاً غيره، فإن كان ما طلقها سابقاً أو ما طلقها إلا واحدة سابقاً، فإنه يراجعها ما دامت في العدة، والسنة أن يشهد شاهدين عدلين أنه راجعها ما دامت في العدة، فإن كان قال ذلك لمنع أو لحث أو تصديق أو تكذيب ما قصد إيقاع الطلاق، قال: عليه الحرام يقصد الطلاق، أو قال: علي الطلاق ما أسافر، ما أكلم فلان، ما أزور فلان، أو عليه الطلاق ما تزورين أهلك، أو عليه الطلاق ما تكلمي فلان، قصده منعه، فهذا مثل ما تقدم حكمه حكم اليمين، فيه كفارة اليمين، والله ولي التوفيق.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7624/حكم-تحريم-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_240/24003.mp3","categories":["الطلاق","الظهار"]},{"id":9465,"question":"المستمع شيخون حنفي محمد مصري الجنسية ويعمل بالمملكة في جدة، بعث برسالة إلى البرنامج يقول فيها: لقد سرقت لي سلسلة من الذهب في البيت، وقد حلفت على زوجتي بالطلاق وقلت لها: بأنت محرمة علي إذا لم توجد السلسلة، ثم إنني عرفت بأنها بريئة وأن سارقًا هو الذي سرق السلسلة، أرجو الإفادة جزاكم الله خيرًا فيما صدر مني؟","title":"كفارة الظهار","answer":"الجواب: هذا فيه تفصيل:\nوفي الحقيقة أنك استعجلت، ولكن هذا فيه تفصيل: فإن كنت أردت أنها محرمة عليك ولو لم تكن عندها السلسلة، وأنها إذا لم تحضر السلسلة فهي محرمة عليك لأنك ظننت أنها عندها وأنها خانتك فيها، فلو كنت جازمًا بهذا وأنها حرام عليك إلا أن تؤدي السلسلة فهذا حكمه حكم الظهار وعليك كفارة الظهار، وهي عتق رقبة مؤمنة ذكر أو أنثى، فإن لم تجد صمت شهرين متتابعين، فإن لم تستطع أطعمت ستين مسكينًا لكل مسكين نصف صاع تكون من قوت البلد من تمر أو أرز أو غيرهما قبل أن تمسها، قبل أن تتصل بها، هذا هو الواجب عليك ؛ لأن هذا في حكم الظهار.\nأما إن كنت ما أردت تحريمها وإنما أردت تشجيعها على البيان والإيضاح، وأنك تتهمها بهذا لكن تريد من هذا الكلام حثها على البيان وعلى رد السلسلة ولم ترد تحريمها، ولكن أردت تخويفها أو تحذيرها من الكتمان، وحثها على البيان فهذا حكمه حكم اليمين، وعليك كفارة اليمين وتكفي، وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد، من تمر أو أرز أو حنطة أو غير ذلك، أو كسوتهم بما يجزئهم في الصلاة كقميص أو إزار ورداء، أو عتق عبد أو أمة مؤمنة، هذا هو الكفارة، هذه هي الكفارة للظهار، فإذا عجز الحالف عن هذه الكفارة ولم يكن عنده قدرة صام ثلاثة أيام.\nوأسأل الله لنا ولك الهداية. نعم.","link":"https://binbaz.org.sa/fatwas/7625/كفارة-الظهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_191/19109.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":9478,"question":"المستمع الذي رمز إلى اسمه بـ (ع. م. ر) من الطائف- رانية، يقول في سؤاله: قلت في إحدى المرات: تحرم علي زوجتي مثل أمي وأختي لو عملت هذا، فما رأيكم في هذه المشكلة وأفيدوني بالنصيحة أفادكم الله؟","title":"حكم الظهار وكفارته","answer":"الجواب: إذا قال الرجل تحرم عليه زوجته كحرمة أمه أو أخته إذا فعلت كيت وكيت، هذا يسمى ظهارًا، وعليه كفارة الظهار وعليه التوبة إلى الله؛ لأن الظهار منكر من القول وزور ليس له فعله، لكن متى قال تحرم عليه زوجته كأمه أو أخته أو جدته أو عمته أو خالته أو نحو ذلك فإذا كلمت فلانًا أو إذا لم تبت عندي أو إذا فعلت كيت وكيت فهذا يسمى ظهارًا.\nفعليه التوبة إلى الله من ذلك، وإذا فعلت ما منعها منه فإنه يكون عليه كفارة الظهار وهي عتق عبد أو أمة مؤمنة، وإن لم يستطع صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا ثلاثين صاعًا، والصاع أربعة حفنات باليدين الممتلئتين المتوسطتين، هذا صاع النبي ﷺ، فعليه ثلاثون صاعًا بصاع النبي ﷺ يقسم بين ستين مسكينًا، كل مسكين له نصف الصاع، وهو كيلو ونصف تقريبًا بالوزن، قبل أن يمسها قبل أن يتصل بها كفارة لما وقع منه من التحريم والظهار، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/7637/حكم-الظهار-وكفارته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_192/19204.mp3","categories":["الطلاق","الظهار"]},{"id":9677,"question":"وهذه رسالة من المرسل أحمد حسن عبدالرحيم يقول في رسالته: أرجو الإفتاء لي عن يمين حلفته على زوجتي وهو كالآتي: قلت: حرام علي لأبيع البيت الذي أسكن فيه -في حالة غضب- ولم أقصد به طلاق زوجتي، ولا نيتي فيه الطلاق أفيدوني عن هذا اليمين بارك الله فيكم؟","title":"حكم من قال: حرام علي لأبيع البيت، ولم يقصد به الطلاق","answer":"الجواب: عليك كفارة يمين إذا كنت حلفت أنك لا تبيعه وبعته فعليك كفارة يمين، وإن كنت حلفت أنك تبيعه ثم هونت عن بيعه فعليك كفارة يمين، الحرام هذا حكمه حكم اليمين، مثل لو قال الإنسان: حرام علي ما أزور فلان، حرام علي ما أكلم فلان، حرام علي ذبيحك يا فلان، حرام علي ضيافتك يا فلان، فيه كفارة يمين؛ لأن الله سبحانه يقول: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ.. [التحريم:1-2] فالحرام في مثل هذا يمين مكفرة، إذا قال: حرام علي أن أبيع بيتي، أو علي حرام أني لا أبيعه ثم باعه، أو حرام علي أني أبيعه ثم باعه، المقصود أنه إذا حرم شيئاً ثم فعله فعليه كفارة اليمين، إلا الزوجة إذا حرم الزوجة قال: هي علي حرام فهذا حكمه حكم الظهار، يكون فيه كفارة الظهار، أما إذا حرم بيع بيته أو بيع سيارته أو حرم أنه ما يأكل ضيافة فلان، أو حرم أنه ما يكلم فلان، أو ما يزور فلان، فهذا كله فيه كفارة اليمين، إطعام عشرة مساكين أو كسوتهم، لكل مسكين نصف صاع من التمر أو غيره من قوت البلد، أو يكسوه كسوة قميص ....... يستره في الصلاة، أو إزار ورداء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7902/حكم-من-قال-حرام-علي-لابيع-البيت-ولم-يقصد-به-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_254/25411.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":9679,"question":"وهذه رسالة من المرسل أحمد حسن عبدالرحيم يقول في رسالته: أرجو الإفتاء لي عن يمين حلفته على زوجتي وهو كالآتي: قلت: حرام علي لأبيع البيت الذي أسكن فيه -في حالة غضب- ولم أقصد به طلاق زوجتي، ولا نيتي فيه الطلاق أفيدوني عن هذا اليمين بارك الله فيكم؟","title":"حكم من قال: حرام علي لأبيع البيت، ولم يقصد به الطلاق","answer":"الجواب: عليك كفارة يمين إذا كنت حلفت أنك لا تبيعه وبعته فعليك كفارة يمين، وإن كنت حلفت أنك تبيعه ثم هونت عن بيعه فعليك كفارة يمين، الحرام هذا حكمه حكم اليمين، مثل لو قال الإنسان: حرام علي ما أزور فلان، حرام علي ما أكلم فلان، حرام علي ذبيحك يا فلان، حرام علي ضيافتك يا فلان، فيه كفارة يمين؛ لأن الله سبحانه يقول: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ.. [التحريم:1-2] فالحرام في مثل هذا يمين مكفرة، إذا قال: حرام علي أن أبيع بيتي، أو علي حرام أني لا أبيعه ثم باعه، أو حرام علي أني أبيعه ثم باعه، المقصود أنه إذا حرم شيئاً ثم فعله فعليه كفارة اليمين، إلا الزوجة إذا حرم الزوجة قال: هي علي حرام فهذا حكمه حكم الظهار، يكون فيه كفارة الظهار، أما إذا حرم بيع بيته أو بيع سيارته أو حرم أنه ما يأكل ضيافة فلان، أو حرم أنه ما يكلم فلان، أو ما يزور فلان، فهذا كله فيه كفارة اليمين، إطعام عشرة مساكين أو كسوتهم، لكل مسكين نصف صاع من التمر أو غيره من قوت البلد، أو يكسوه كسوة قميص ....... يستره في الصلاة، أو إزار ورداء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7902/حكم-من-قال-حرام-علي-لابيع-البيت-ولم-يقصد-به-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_254/25411.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":9745,"question":"أخيراً يقول الأخ المصري من مركز أبو حماد يقول: حصل بيني وبين أهل زوجتي خلاف، فقلت لزوجتي: إذا ذهبت إلى منزل أبوك فتكونين حراماً علي كأمي وأختي، فإذا ذهبت إلى منزل أبوها بعد ذلك، ماذا أفعل، أفيدوني أفادكم الله؟","title":"حكم من قال لزوجته: أنت حرام علي كأمي","answer":"الجواب: هذا يسمى الظهار، إذا فعلت يكون ظهاراً، وعليك كفارة الظهار، وهي عتق رقبة مؤمنة فإن لم يستطع صام شهرين متتابعين، فإن عجز أطعم ستين مسكيناً.\nوالواجب عليك ترك ذلك؛ لأن هذا منكر من القول فليس له فعل ذلك، بل يتقي الله ويحرص على ترك هذه الأشياء، لكن متى فعلها فعليه التوبة والاستغفار، وعليه الكفارة قبل أن يمسها: قَبْلِ أَنْ يَتَمَاسَّا [المجادلة:3]. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7920/حكم-من-قال-لزوجته-انت-حرام-علي-كامي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25611.mp3","categories":["الطلاق","الظهار"]},{"id":9816,"question":"وهذه رسالة من حسين محمد الزبير سوداني الجنسية يعمل في الكويت، يقول في رسالته: حلفت بالحرام أن لا أمضي في هذا البلد إلا سنة واحدة وأرجع، لكني قد تجاوزت السنة ولم أرجع ولم أوف بحلفي، فماذا أعمل وأنا أريد الآن السفر وأنا متزوج فخشيت من هذا الحلف أن يؤثر علي أفيدوني أفادكم الله؟","title":"الحلف بالحرام فيه كفارة يمين","answer":"الجواب: إذا كان المقصود من هذا الحلف حث نفسك على الخروج وعدم الزيادة على السنة ولم ترد تحريم زوجتك، وإنما أردت حث نفسك على أن تخرج من البلد وتسافر قبل السنة، فإن عليك كفارة يمين، إذا زدت على السنة عليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم، لقوله : يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:1-2].\nفالمقصود: أن عليك كفارة يمين وهي إطعام عشرة مساكين من قوت البلد لكل مسكين نصف صاع، يعني: كيلو ونصف تقريباً من قوت البلد من رز أو تمر أو حنطة أو غير ذلك، وعليك التوبة والاستغفار؛ لأن التحريم لا يجوز.\nأما إن كنت أردت تحريم زوجتك فإن عليك كفارة الظهار، وهي عتق رقبة مؤمنة، فإن لم يتيسر ذلك تصوم شهرين متتابعين، فإن لم تستطع ذلك تطعم ستين مسكيناً ثلاثين صاعاً من التمر أو الحنطة أو الرز أو الشعير لكل مسكين نصف صاع، يعني: كيلو ونصف تقريباً لكل واحد من قوت البلد من تمر أو غيره أو أرز أو حنطة ونحو ذلك قبل أن تمسها قبل أن تقربها؛ لأن هذا في حكم الظهار، إذا كنت أردت تحريم زوجتك إذا زدت على السنة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7992/الحلف-بالحرام-فيه-كفارة-يمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_260/26013.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":9858,"question":"وله استفتاء ثالث أيضًا يقول فيه: ما حكم المرأة التي تقول لزوجها: الله يحرمك عليَّ، وتروح إلى بيت أهلها وترجع بعد ذلك إلى بيت الزوجية؟","title":"حكم تحريم المرأة زوجها على نفسها","answer":"الجواب: هذا لفظه لفظ الخبر، ومعناه الدعاء، ولا وجه له ولا يحصل به شيء، ولا يترتب عليه شيء فقولها: الله يحرمك، أو الله يجعلك علي حرام، ما يترتب عليه شيء لكنه دعاء لا ينبغي منها، وهو معناه طلب شيء يجعلها محرمة عليه وهذا لا ينبغي منها.\nأما لو قالت: أنت حرام علي، أو أنت محرم علي، فإن هذا أولًا لا يجوز لها، وثانيًا عليها كفارة يمين إذا فعلت ذلك؛ لأن المسلم إذا حرم الحلال عليه كفارة يمين ؛ لقول الله سبحانه: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:1-2]، فمن حرم ما أحل الله له كأن يحرم طعام فلان، أو زيارة فلان، أو شراب فلان، أو الجلوس عند فلان، أو كلام فلان، عليه كفارة يمين، وهكذا إذا قالت المرأة: زوجي حرام علي، أو أنت علي مثل أبي أو ما أشبه ذلك فإن هذا كلام منكر وعليها التوبة إلى الله من ذلك، وعليها كفارة اليمين؛ لأن الظهار لا يكون من النساء إنما يكون من الرجال للنساء، أما المرأة فليس منها ظهار للزوج؛ لأن الله قال سبحانه: وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ [المجادلة:3]، فالظهار للزوج مع المرأة، أما هي إذا ظاهرت من زوجها أو حرمت زوجها فعليها كفارة اليمين، وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد من تمر أو غيره، أو كسوتهم للواحد ما يجزئ في الصلاة من قميص أو إزار ورداء، أو عتق رقبة؛ عتق عبد أو عبدة ، أحد الثلاث: إما إطعام عشرة مساكين، وإما كسوتهم، وإما إعتاق رقبة مؤمنة، فإن عجز عن ذلك ولم يستطع هذه الكفارة أجزأه أن يصوم ثلاثة أيام عند العجز. نعم.\nالمقدم: يعني حالة هذه لا تعتبر الآن يعني عليها كفارة فيها؟\nالشيخ: لا؛ لأنها دعاء ما ....: الله يحرمكم ما فيه كفارة. نعم.","link":"https://binbaz.org.sa/fatwas/8019/حكم-تحريم-المراة-زوجها-على-نفسها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_198/19811.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":9972,"question":"وهذه رسالة وردت من سائل رمز لاسمه بأخيكم في الإسلام من السودان، يقول في رسالته: أنا شاب أبلغ من العمر الثامنة والعشرين تزوجت في هذا العام إكمالًا لديني، ولكن مع الأسف لقد حلفت بقول: علي الحرام، علمًا بأنني في شعوري ولست مخمورًا ولكنني حلفت وأنا لا أقصد بأن أحرم زوجتي علي، فبكيت وندمت أشد الندم على الذي حصل مني، وصرت أستغفر الله وأدعوه في كل صلاة أن يعفو عني وتصدقت بإطعام ستين مسكيناً لكي يغفر الله لي هذا الذنب، فأسأل عن حكم ذلك؟ بارك الله فيكم.","title":"حكم من قال: (زوجتي علي حرام)","answer":"","link":"https://binbaz.org.sa/fatwas/8127/حكم-من-قال-زوجتي-علي-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27408.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":11211,"question":"هذا السائل من الطائف أبو فيصل يقول: يا سماحة الشيخ! بأنه قبل ثلاثة أعوام حلف على زوجته بكلمة الحرام، بأنك لو فعلت كذا وكذا لن تسافري إلى أهلك وقد فعلت ذلك الأمر، يقول: ولنسيان الحلف بالحرام فقد سافرنا إلى أهلها، وقد تكرر ذلك الأمر منها مرتين، وتكرر أيضًا مني الحلف بالحرام، أرجو من فضيلتكم التوجيه؟","title":"حكم من حلف بالحرام ألا تفعل زوجته شيئًا ففعلته ناسية","answer":"الجواب:  إذا كان السفر عن نسيان فلا شيء، يقول الرب جل وعلا: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286]، وثبت عن رسول الله: إن الله جل وعلا قد فعل، فالناسي لا شيء عليه، إذا قلت: علي الحرام لا تسافرين في يوم كذا وسافرت نسيانًا فلا شيء.  أما إن كانت عمدًا وأنت تقصد منعها ألا تسافر، قلت: علي الحرام، مقصودك منعها، لم تقصد تحريمها إنما قصدت المنع والتخويف فهذا فيه كفارة اليمين إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فمن عجز صام ثلاثة أيام، إذا كان المقصود التخويف والمنع والتحذير. أما إذا كان المقصود تحريمها عليك إذا سافرت فعندها يجب عليك كفارة الظهار وهي: عتق رقبة، فإن عجزت تصوم شهرين متتابعين ستين يومًا، فإن عجزت تطعم ستين مسكينًا ثلاثين صاعًا تسعين كيلو، كل فقير له نصف الصاع كيلو ونصف. أما إذا كان المقصود التحذير والتخويف، قلت: علي الحرام لا تسافرين، وقصدك التخويف والتحذير فهذا كفارة يمين، إذا فعلت المحلوف عليه عامدة، أما إن كانت ناسية فلا شيء عليك. نعم.","link":"https://binbaz.org.sa/fatwas/9392/حكم-من-حلف-بالحرام-الا-تفعل-زوجته-شيىا-ففعلته-ناسية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29111.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":11565,"question":"المستمع جابر محمد علي زيدان من جمهورية مصر العربية يقول في سؤال مطول: إنني أقسمت على زوجتي بالطلاق، وعلى المذاهب الأربعة، بأنك لو ذهبت إلى منزل والدك في حال زعل بدون علمي؛ فتكوني محرمة علي مثل والدتي، علمًا بأن لديها طفل وفي حالة حمل، وعلمًا بأن هذا أول طلاق صدر بيننا، فما الحكم؟ وبم توجهوننا؟ جزاكم الله خيرًا.","title":"حكم الحلف بالطلاق مع المظاهرة من الزوجة","answer":"الجواب:  هذا فيه تفصيل: إن كنت أردت الطلاق والتحريم جميعًا، فإنها يقع عليها طلقة، وتحرم عليك كظهر أمك، وعليك كفارة الظهار، وهي عتق رقبة مؤمنة، فإن عجزت؛ تصم شهرين متتابعين، فإن عجزت تطعم ستين مسكينًا، ثلاثين صاعًا، كل صاع بين اثنين، والصاع ثلاثة كيلو تقريبًا، وكل واحد يعطى نصف الصاع كيلو ونصف من قوت البلد، من تمر أو أرز أو غيرهما، إذا كنت تعجز عن العتق، وعن صيام شهرين متتابعين، ويقع عليها طلقة واحدة تراجعها في العدة، إذا كنت لم تطلقها قبلها طلقتين. أما إن كنت قلت: علي الطلاق تريد بذلك التحريم فقط، ما أردت إيقاع الطلاق، يعني عليك الطلاق أن تحرمها، قصدك عليك الطلاق أن تحرمها قد حرمتها، وعليك كفارة الظهار فقط وهي سهلة، ولا يقع الطلاق، إذا كنت أردت بالطلاق التحريم، يعني: إن قلت: علي الطلاق يعني: أنها محرمة عليك كأمك، وليس قصدك تطليقها إنما قصدك تحريمها، فهذا يكون فيه كفارة الظهار فقط، ولا يقع طلاق. أما إن كنت أردت الأمرين: أنها يعني تطلق، وتحرم، كظهر أمك، فإنها يقع عليها طلقة واحدة، وتراجعها إذا ما كان قبلها طلقتان، وعليك أيضًا كفارة الظهار؛ لأن تحريمها كأمك، وكفارة الظهار -كما سبق- مرتبة أولًا: عتق رقبة مؤمنة إن تيسر، فإن لم يتيسر؛ فصيام شهرين متتابعين، ستين يومًا، فإن عجزت عن هذه؛ تطعم ستين مسكينًا، ثلاثين صاعًا، كل صاع مقداره ثلاثة كيلو تقريبًا، كل مسكين يعطى صاعًا، كيلو ونصف تقريبًا من قوت البلد، من تمر أو أرز أو حنطة أو شعير أو دخن، أو على حسب حال البلد، مع التوبة والاستغفار، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9748/حكم-الحلف-بالطلاق-مع-المظاهرة-من-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29714.mp3","categories":["الطلاق","الظهار"]},{"id":12269,"question":"المستمع (م. أ. م) مصري بعث برسالة يقول فيها: حصلت مشادة عنيفة بيني وبين أحد أبناء عمي، وعندما ذهبت إلى المنزل صادفت زوجتي فبادرتها قائلًا: إذا ذهبت إلى بيت ابن عمي؛ فأنت تحرمي، ولم أكمل: علي، وكان هذا منذ مدة طويلة، وحصلت حالة وفاة في بيت ابن عمي، وأنا موجود في العراق، فذهبت زوجتي دون علمي، ولي منها ثلاثة أطفال، ولم أفاتحها بموضوع ذهابها من أجل الأطفال، وعلاقتي بها علاقة طبيعية، لكني أخشى أن يكون تحريمي قد وقع، أو أن يكون علي كفارة، أرجو إفادتي جزاكم الله خيرًا.","title":"حكم من حرَّم زوجته إن هي فعلت شيئاً منعها منه","answer":"الجواب:  إذا كان قصدك منعها من الذهاب إلى بيت ابن عمك، وليس قصدك تحريمها، ولا طلاقها؛ فعليك كفارة يمين: وهي إطعام عشرة مساكين، أو كسوتهم، عشرة عدد أصابعك، وهي نصف صاع لكل واحد، بصاع النبي -عليه الصلاة والسلام- ومقدار ذلك كيلو ونصف تقريبًا من الرز أو التمر أو الحنطة، يدفع إلى بعض الفقراء، أو كسوتهم، كل واحد يكسى قميصًا، كما قال تعالى في الأيمان: وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ [المائدة:89] الآية، قد أفتى بهذا جمع من الصحابة  ويدل على هذا قوله -جل وعلا-: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ [التحريم:1] جاء في التفسير: أن ذلك تحريمه لأمته، وقال آخرون: تحريمه للعسل. فالمقصود: أن الإنسان إذا قال مثل هذا الكلام: إن ذهبت إلى بيت ابن عمي، أو إلى بيت آل فلان؛ فأنت حرام علي، قصده المنع؛ فإن عليه كفارة يمين إذا ذهبت إليهم، إما إن كان قصدك تحريمها، أو طلاقها إن ذهبت؛ فإنها تحرم عليك حتى تكفر كفارة الظهار، وهي عتق رقبة مؤمنة، فإن عجزت؛ تصم شهرين متتابعين، فإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا قبل أن تمسها، قبل أن تقربها، وإذا كنت قد قربتها؛ تمتنع حتى تكفر هذه الكفارة، وهي مرتبة، أولًا: عتق رقبة مؤمنة، فإن عجزت؛ تصم شهرين متتابعين، ستين يومًا، فإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا، بصاع النبي ﷺ، ومقدار الصاع ثلاثة كيلو تقريبًا، لكل مسكين نصف صاع، كيلو ونصف تقريبًا للستين، قبل أن تمسها، هذا إذا كنت قصدت التحريم، إذا ذهبت، أما إن كنت قصدت الطلاق، ما قصدت التحريم؛ فيقع طلقة واحدة، وتراجعها إذا كان ما قبلها طلقتان، إذا كنت لم تطلقها قبل هذا طلقتين تراجعها، والحمد لله، تقول: اشهد يا فلان وفلان أني راجعتها، أو تقول: قد راجعتك يا فلانة، يكفي، وإذا شاهدت عدلين يكون أنسب وأفضل. أما إذا كنت ما أردت تحريمها، ولا طلاقها، وإنما أردت تهديدها، ومنعها وتخويفها، ولم ترد لا طلاقًا، ولا تحريمًا؛ فإن عليك كفارة اليمين فقط، ويكون لهذا الكلام حكم اليمين، كما تقدم، وهي إطعام عشرة مساكين، لكل مسكين نصف صاع من التمر، أو الحنطة، أو الرز، مقداره كيلو ونصف تقريبًا، أو تكسوهم كسوة، كل واحد قميصًا ... أو إزارًا ورداءًا يجزئه في الصلاة، يكفي هذا، إذا كنت ما أردت الطلاق ولا التحريم، وإنما أردت تهديدها ومنعها، وينبغي لك أن تحذر مثل هذا، وألا تستعمله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10469/حكم-من-حرم-زوجته-ان-هي-فعلت-شيىا-منعها-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_450/45006.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":12872,"question":"المستمع: محمد عبدالفتاح بعث برسالة يقول فيها: أنا متزوج منذ عشر سنوات، وعندي ثلاثة أولاد، قلت لزوجتي عندما سافرت: لا تذهبي لزيارة أهلك، وإذا ذهبت أنت محرمة، وقلتها ثلاث مرات، لم أعرف معناها جيدًا في ذلك الوقت، المهم في الأمر أنها ذهبت رغم ما قلت لها، أرجو إفادتي يا سماحة الشيخ عن الحكم، جزاكم الله خيرًا.","title":"حكم تحريم الزوجة","answer":"الجواب:  هذا يختلف بحسب النية، إن كنت أردت تحريمها إذا خرجت، أو طلاقها إذا خرجت؛ فإنها تحرم إذا خرجت، وعليك كفارة الظهار، عتق رقبة مؤمنة، فإن عجزت؛ تصوم شهرين متتابعين، فإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا، كل مسكين له نصف الصاع من التمر، أو الأرز، أو غيرهما من قوت البلد. فأما إن كنت أردت الطلاق يقع طلقة واحدة، إذا أردت إيقاع الطلاق بخروجها، بهذا المعنى بقولك: محرمة إن أردت الطلاق فالأعمال بالنيات، يقع طلقة وتراجعها، تقول: قد راجعت زوجتي، وتشهد اثنين الأفضل من إخوانك الطيبين أنك راجعتها، إذا كنت ما طلقتها قبل ذلك طلقتين. فأما إن كنت ما أردت الطلاق، ولا التحريم، إنما أردت منعها، حين قلت: إن ذهبت أردت المنع فقط، ولم تقصد لا تحريمًا، ولا طلاقًا، إنما أردت منعها وتهديدها، فعليك كفارة يمين، ولا يقع شيء بخروجها على الصحيح من كلام أهل العلم؛ لأن هذا التعليق بهذه النية في حكم اليمين، إذا كان بنية المنع، أو التهديد، لا بنية الطلاق، ولا بنية التحريم، فهذا يكون في حكم اليمين بهذه النية، والرسول  قال: الأعمال بالنيات وأنت أعلم بنيتك، نسأل الله لنا ولك التوفيق، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11087/حكم-تحريم-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46604.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":12952,"question":"هذا السائل (ع. م) سوري ومقيم في الأردن يقول: لقد حرَّمتُ زوجتي عليَّ لمدة سنة، وبعد شهر من الزمن رددتُها، فما الحكم في ذلك يا سماحة الشيخ، مأجورين؟","title":"حكم من حرم زوجته على نفسه سنة ثم ردها","answer":"الجواب:  إذا كنت جامعتها؛ عليك كفارة الظهار، وإن كنت رديتها في البيت، ولكن ما جامعتها؛ ما عليك شيء حتى تتم السنة، فإن جامعتها قبل السنة؛ فعليك كفارة الظهار المذكورة في سورة المجادلة، وهي عتق رقبة مؤمنة، فإن عجزت؛ تصوم شهرين متتابعين، فإن لم تستطع؛ تطعم ستين مسكينًا، ثلاثين صاعًا قبل أن تقربها، ثلاثين صاعًا، لكل مسكين نصف صاع، يعني: كيلو ونصف كل واحد، تسعين كيلو، كل واحد له كيلو ونصف قبل أن تقربها عند العجز عن العتق والعجز عن الصوم، هذه كفارة الظهار، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11169/حكم-من-حرم-زوجته-على-نفسه-سنة-ثم-ردها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50211.mp3","categories":["الطلاق","الظهار"]},{"id":14405,"question":"هذا (المهدي . ح. ع) أرسل بمجموعة من الأسئلة، يقول في السؤال الأول: لقد ارتكبت ذنبًا، وحلفت بأن لو عدت إلى هذا الذنب مرة ثانية تكون زوجتي علي كظهر أمي، ولكنني عدت ثانيًا، و هل يقع مثل هذا الظهار؟ وما هي الكفارة سماحة الشيخ؟","title":"حكم من حلف بالظهار على ترك ذنب ثم عاد","answer":"الجواب: نعم، إذا قلت هذا، ثم عدت يكون قد ظاهرت منها، عليك كفارة الظهار لا تقربها، ولا تمسها حتى تعتق رقبة، فإن عجزت تصوم شهرين متتابعين، ستين يومًا، فإن عجزت تطعم ستين مسكينًا، هذه كفارة الظهار، ولا يجوز لك هذا العمل، هذا ما يجوز، سماه الله منكرًا من القول وزورًا. فالواجب عليك أن تحذر مثل هذه الأيمان التي فيها المظاهرة، وفيها التحريم من زوجتك، لكن متى فعلت هذا، قلت: متى فعلت هذا فإن زوجتي كظهر أمي علي، تحرم علي يكون ظهار، عليك أن تجتنبها، وتمتنع منها حتى تكفر كفارة الظهار، وهي عتق رقبة، فإن عجزت تصوم شهرين متتابعين؛ ستين يومًا، فإن عجزت تطعم ستين مسكينًا، كل مسكين له نصف الصاع، كيلو ونصف تقريبًا قبل أن تقربها، كما نص الله على هذا في كتابه الكريم في سورة المجادلة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12887/حكم-من-حلف-بالظهار-على-ترك-ذنب-ثم-عاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55302.mp3","categories":["الطلاق","الظهار","الرجعة"]},{"id":14698,"question":"المستمع (م. م. م) مقيم في المملكة، وهو سوداني، بعث برسالة كتبها بلهجته العامية، مفهوم ما في هذه الرسالة يقول: على إثر نزاع بينه وبين زوجته حلف بالحرام لا يأكل من طعامها، ولا يصلها، ففعل، ويسأل عن الحكم.","title":"حكم من حلف بالحرام ألا يفعل شيئًا ما ثم فعله","answer":"الجواب: هذا يختلف بحسب النية، إذا كان حلفه بالحرام ألا يأكل من طعامها قصده الامتناع من ذلك يقصد الامتناع مما حلف عليه، وليس يقصد تحريمها هي، وإنما قصد من ذلك أن يمتنع مما حلف عليه، فهذا يكفيه كفارة يمين، مع التوبة إلى الله، والاستغفار.  وكفارة اليمين: إطعام عشرة مساكين من قوت البلد، أو كسوتهم، كل واحد يعطى نصف الصاع من التمر أو الأرز أو البر مقداره كيلو ونصف تقريبًا، أو يكسو كل واحد منهم كسوة تجزئهم في الصلاة، كالقميص أو إزار ورداء، فإن كان عاجزًا فقيرًا لا يستطيع ذلك صام ثلاثة أيام. أما إن كان قصد تحريمها، وأنها حرام عليه كأمه وأخته، فهذا يسمى ظهارًا إذا كان قصده ذلك، فإذا أكل أو فعل شيئًا مما حرم عليه فإنه يكون عليه كفارة الظهار، المذكورة في سورة المجادلة قَدْ سَمِعَ [المجادلة:1] وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين ستين يومًا، فإن عجز أطعم ستين مسكينًا كل مسكين يعطى نصف صاع من قوت البلد من تمر أو أرز أو غيرهما، وهو كيلو ونصف تقريبًا، وإن عشاهم أو غداهم كفى ذلك، ستين مسكينًا، ستين فقيرًا، يعطون ثلاثين صاعًا، كل صاع بين اثنين، هذا إن كان قصد تحريمها. أما إذا كان ما قصد إلا الامتناع من الأكل ونحوه، وليس قصده تحريمها، فإنه يكفيه كفارة اليمين، كما تقدم.\nالمقدم: جزاكم الله خيرًا، لو تكرمتم إعادة مقدار ما يعادل الصاع بالكيلو سماحة الشيخ؟\nالشيخ: ثلاثة كيلو، يعادل الصاع ثلاثة كيلو تقريبًا، يعادل الصاع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13224/حكم-من-حلف-بالحرام-الا-يفعل-شيىا-ما-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62911.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":14705,"question":"المستمع (م. م. م) مقيم في المملكة، وهو سوداني، بعث برسالة كتبها بلهجته العامية، مفهوم ما في هذه الرسالة يقول: على إثر نزاع بينه وبين زوجته حلف بالحرام لا يأكل من طعامها، ولا يصلها، ففعل، ويسأل عن الحكم.","title":"حكم من حلف بالحرام ألا يفعل شيئًا ما ثم فعله","answer":"الجواب: هذا يختلف بحسب النية، إذا كان حلفه بالحرام ألا يأكل من طعامها قصده الامتناع من ذلك يقصد الامتناع مما حلف عليه، وليس يقصد تحريمها هي، وإنما قصد من ذلك أن يمتنع مما حلف عليه، فهذا يكفيه كفارة يمين، مع التوبة إلى الله، والاستغفار.  وكفارة اليمين: إطعام عشرة مساكين من قوت البلد، أو كسوتهم، كل واحد يعطى نصف الصاع من التمر أو الأرز أو البر مقداره كيلو ونصف تقريبًا، أو يكسو كل واحد منهم كسوة تجزئهم في الصلاة، كالقميص أو إزار ورداء، فإن كان عاجزًا فقيرًا لا يستطيع ذلك صام ثلاثة أيام. أما إن كان قصد تحريمها، وأنها حرام عليه كأمه وأخته، فهذا يسمى ظهارًا إذا كان قصده ذلك، فإذا أكل أو فعل شيئًا مما حرم عليه فإنه يكون عليه كفارة الظهار، المذكورة في سورة المجادلة قَدْ سَمِعَ [المجادلة:1] وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين ستين يومًا، فإن عجز أطعم ستين مسكينًا كل مسكين يعطى نصف صاع من قوت البلد من تمر أو أرز أو غيرهما، وهو كيلو ونصف تقريبًا، وإن عشاهم أو غداهم كفى ذلك، ستين مسكينًا، ستين فقيرًا، يعطون ثلاثين صاعًا، كل صاع بين اثنين، هذا إن كان قصد تحريمها. أما إذا كان ما قصد إلا الامتناع من الأكل ونحوه، وليس قصده تحريمها، فإنه يكفيه كفارة اليمين، كما تقدم.\nالمقدم: جزاكم الله خيرًا، لو تكرمتم إعادة مقدار ما يعادل الصاع بالكيلو سماحة الشيخ؟\nالشيخ: ثلاثة كيلو، يعادل الصاع ثلاثة كيلو تقريبًا، يعادل الصاع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13224/حكم-من-حلف-بالحرام-الا-يفعل-شيىا-ما-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62911.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":14836,"question":"يقول: ما حكم من قال: تحرم علي زوجتي؟","title":"حكم من قال: تحرم علي زوجتي","answer":"الجواب: هذا حكمه حكم الظهار، إذا قال إنسان: تحرم علي زوجتي، أو هي حرام علي زوجتي، أو حرمها الله علي زوجتي، أو هي كظهر أمي، أو كظهر أختي أو كأختي، أو كأمي، يقصد تحريمها فهو ظهار، يسمى ظهارًا، وعليه كفارة الظهار قبل أن يمسها، وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا، ثلاثين صاعًا، كل صاع بين اثنين قبل أن يمسها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13328/حكم-من-قال-تحرم-علي-زوجتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63817.mp3","categories":["الطلاق","الظهار"]},{"id":14839,"question":"يقول: ما حكم من قال: تحرم علي زوجتي؟","title":"حكم من قال: تحرم علي زوجتي","answer":"الجواب: هذا حكمه حكم الظهار، إذا قال إنسان: تحرم علي زوجتي، أو هي حرام علي زوجتي، أو حرمها الله علي زوجتي، أو هي كظهر أمي، أو كظهر أختي أو كأختي، أو كأمي، يقصد تحريمها فهو ظهار، يسمى ظهارًا، وعليه كفارة الظهار قبل أن يمسها، وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا، ثلاثين صاعًا، كل صاع بين اثنين قبل أن يمسها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13328/حكم-من-قال-تحرم-علي-زوجتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63817.mp3","categories":["الطلاق","الظهار"]},{"id":15301,"question":"سؤاله الثاني يقول: لو أن شخصًا غضب من زوجته، وقال لها: لا أريد أن أراك، وسأتخلص منك، وسأعاملك مثل أختي، وكانت نيته تهديدها فقط، وخاصة لو قال لها: أنت بالنسبة لي مثل أختي، فما الحكم في ذلك؟ هل هي طالق بالنسبة له؟علمًا بأنه يجهل كلمة أنت مثل أختي، أو لا أريد أن أراك، ويعتقد فقط أن المرأة لا تطلق إلا بحلف بالطلاق بلفظه، فما الحكم في ذلك؟ وهل هي طالق؟ وماذا يفعل إذا كانت طالقًا ليستردها؟","title":"حكم قوله لزوجته: لا أريد أن أراك، وأنت مثل أختي","answer":"الجواب: هذا الكلام وأشباهه ليس بطلاق؛ إذا قال: لا أريدك، أو لا أحب أن أراك، أو سوف أطلقك، هذا وعيد، سوف أطلقك، هذا وعيد من باب الوعيد، أو لا أحب أن أراك، هذا يبين كراهته لها، وليس هذا بطلاق.\nالمقدم: ولا كناية؟\nالجواب: ولا كناية، أما إذا قال: أنت علي مثل أختي، أو مثل أمي، هذا يسمى ظهارًا، إذا كان أراد بذلك تحريمها أو أراد بذلك كراهتها، وإنزالها منزلة محارمه، أما إذا كان أراد بذلك إكرامها، وأنها مثل أخته في المحبة، يعني: يحبها كأخته ويقدرها تقديرًا هذا ما يصير ظهار. أما إذا قال: أنت مثل أختي، أو مثل أمي، أو خالتي قصده تحريمها عليه، وأنها لا تحل له، هذا معناه الظهار، يعني معناه: أنها حرام عليه، فعليه كفارة الظهار، وهي عتق رقبة مؤمنة، فإن لم يستطع صام شهرين متتابعين، وإن عجز أطعم ستين مسكينًا، ثلاثين صاعًا كل صاع بين اثنين من قوت البلد من حنطة أو أرز أو نحو ذلك، قبل أن يمسها، قبل أن يجامعها، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13815/حكم-قوله-لزوجته-لا-اريد-ان-اراك-وانت-مثل-اختي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_682/nour_68204.mp3","categories":["الطلاق","الظهار"]},{"id":15320,"question":"هذا سؤال من المستمع: أحمد خليل الشريف، من جمهورية السودان، مدرس باليمن الشمالي، يقول: حدثت خمس مشاكل مع زوجتي منذ حوالي ثمان سنوات، وعلى إثرها تركت البيت إلى بيت أبيها، وطالت المدة، وطلبتها من أهلها وأقاربها؛ وذلك لحاجتي إليها؛ ولعدم اتساع المشاكل كلما طالت المدة، وقد حان موعد عيد الفطر، وكنت أريد أن تكون زوجتي في بيتها، وعلى أمل أن تعود، وعندما جاءني خبر بأنها لن تعود حلفت يمينًا، قلت: علي الطلاق إذا لم ترجع قبل العيد، أو قبل الشهر؛ تكون مطلقة، واتصلت بعد اليمين بأهلها حتى تحضر قبل الميعاد، لكن والدها رفض ذلك، ولم تحضر، وكذلك زوجتي لم تسمع بهذه اليمين إلا بعد أن تصالحنا، وذهبت بعدها إلى أحد المشايخ لرد اليمين، ولم أتذكر بماذا أفتاني هذه مرة.والمرة الأخرى حلفت يمينًا بالطلاق على زوجتي، قلت: علي الطلاق إذا سلمت على فلان تكوني مطلقة، أريد منعها من السلام على هذا الإنسان الذي لا أستريح له، ولا سيما قد يجمعنا مكان واحد؛ لأنه قريب، ولكنها سلمت عليه.يقول: وفي المرة الثالثة على إثر خلاف أرادت الخروج من البيت، وكنت أريد منعها من الخروج، وتهديدها حتى لا تخرج، فيكون هناك مشاكل أكثر، فحلفت يمين طلاق، وقلت في نفس اليمين: تكوني محرمة علي مثل أمي وأختي إذا خرجت من باب البيت، فرجوتها ألا تخرج من باب البيت، ولكنها خرجت، وسألت عن هذا أيضًا، فقيل: أطعم ستين مسكينًا، وفعلت، وقال: لك طلقة واحدة.وفي المرة الرابعة سمعت زوجتي تقول لأحد أبنائي: (يا ابن الكلب) فحلفت يمينًا، قلت: علي الطلاق لو قلت ذلك مرةً ثانية تكوني طالقة، ولم أسمعها قالت شيئًا، وإنما قالت لي بعد هذا اليمين: أنا سهوت وقلت: (يا أولاد الكلب) لأولادي، علمًا بأنني حلفت هذه اليمين، وهي لم تتطهر بعد من العادة الشهرية.وفي المرة الخامسة على إثر سوء تفاهم معها هددتها بالطلاق إذا لم تكف عن الصياح، ولكنها لم تكف مرة تلو المرة، وزادت من صياحها، فغضبت غضبًا شديدًا، وخرج الكلام بعد مقاومة مني له مندفعًا بالغضب قلت: علي الطلاق أنت مطلقة في ذلك الوقت، وتكوني محرمة علي مثل أمي وأختي، وبعدها تيقنت أنني خسرت أولادي وزوجتي، غير أني من شدة الغضب لم أتذكر أنني قلت لها: تكوني محرمة علي مثل أمي وأختي، وأسأل؛ هل بالغضب الشديد لا يقع الطلاق؟ وما شدته؟ وهل من الضرورة ألا أتذكر شيئًا مما قلته على الإطلاق؟ وهل هذا اليمين يقع؟ رغم أني قلته نتيجة لغضب شديد، فماذا ترون في هذه الحالات الخمس؟أفيدوني بارك الله فيكم، هل بقيت لي فرصة للعيش مع زوجتي أم لا؟","title":"مسائل في الحلف بالحرام والطلاق","answer":"الجواب: على كل حال ما ينبغي للسائل أن يتساهل بهذا الأمر، ويكثر من الطلاق، ويهدد بالطلاق، بل ينبغي له أن يحفظ لسانه، وهكذا كل مسلم، ينبغي له أن لا يتساهل في الطلاق، بل ينبغي له أن يحفظ لسانه من الطلاق، وأن يهدد بغير الطلاق، ويتوعد بغير الطلاق، وينصح زوجته عند المخالفة بما يرى من النصيحة، أما الطلاق فينبغي أن يكون بعيدًا؛ لأن ذلك قد يضر بحاله مع زوجته، وقد يفضي إلى فراقها، فينبغي له ألا يهدد بالطلاق، وألا يستعمله مهما أمكن. وأما ما وقع منه في هذه المسائل الخمس؛ فالطلاق الذي أراد به تهديدها، ومنعها، وما أراد إيقاع الطلاق حين قال لها: إن جاء العيد، أو خرج الشهر قبل أن تحضري؛ فأنت طالق، إن كان أراد بهذا إيقاع الطلاق؛ وقع طلقة، وإن كان ما أراد بذلك إيقاع الطلاق، وإنما أراد منعها من البقاء عند أهلها؛ حتى تأتي قبل العيد، وأراد بهذا تخويفها من مغبة هذه اليمين فإنه لا يقع شيء، وعليه كفارة يمين. وهكذا منعها من السلام على الشخص المعين، إذا كان أراد منعها كما قال، ولم يرد إيقاع الطلاق؛ فإن الطلاق لا يقع، وعليه كفارة يمين عن سلامها له، إذا كان أراد منعها من السلام، ولم يرد إيقاع الطلاق. وهكذا منعها من الخروج من البيت، إذا كان أراد عدم خروجها، وإنما أراد تخويفها بالطلاق حتى لا تخرج، ثم خرجت، فعليه كفارة يمين، في هذا كله، أما إذا كان أراد إيقاع الطلاق؛ فإنها تقع طلقة. وهذا طلاق متعدد، والمسألة تحتاج إلى عناية، ونظر في موضوعه، فإن كانت الزوجة موجودة في الرياض؛ فنرى أنه يحضر عندي هو وزوجته؛ حتى ننظر في أمرهما جميعًا بالتفصيل، وحتى تكون الفتوى على أمرٍ واضح. والشيء الذي فعلته ناسيةً؛ لا يقع به شيء، إذا كانت كلمت من منعها من تكليمه، سهوًا ناسيةً، فلا يقع شيء بذلك، ولا عليك كفارة، فيما إذا كانت فعلت المحلوف عليه ناسيةً -ساهية-؛ لأن الله يقول سبحانه: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا[البقرة:286]. وهكذا إذا اشتد الغضب، ولم يملك نفسه.......، الغضب شديدًا؛ لأنها خالفته، ونازعته شديدًا، وتكلمت عليه كلامًا يعني: سبب شدة غضبه، وعدم استطاعته قهر نفسه؛ فإنه بهذه الحالة لا يقع الطلاق، فإنه في هذه الحال يشبه حال من لا عقل له عند شدة الغضب؛ لأنه لا يملك نفسه، ولا يستطيع قهرها بسبب الغضب الشديد، والنزاع الشديد، أو الكلام الخبيث الذي قالت له؛ حتى اشتد غضبه، فإنه لا يقع به الطلاق. وقولها: يا ابن الكلب، أو يا بني الكلب؛ إذا كانت ساهيةً؛ فإنه لا يقع شيء بذلك، ولا يلزمه كفارة يمين بذلك، فينبغي له أن يتوقف عن الطلاق، ويحذر هذا الاستعمال الذي قد يفضي به إلى فراق أهله، وقد يسبب مشاكل عليه، فينبغي له أن يحذرها. ينبغي لك -أيها السائل- أن تحذر مثل هذا، وإذا حضرت مع زوجتك عندي؛ فهو يكون أولى، حتى نسألها عما قلت، ونسألك عما قلت، وحتى يحضر معها وليها كأخيها، أو أبيها؛ حتى ننهي الموضوع على طريقة واضحة، وبعد سؤالكما جميعًا والولي عن كل ما وقع، هذا يكون أحوط وأولى.\nالمقدم: السائل مقيم في اليمن علي أي حال.\nالشيخ: إذا كان في اليمن فعليه أن يتصل بالعلماء هو وزوجته ووليها، أحسن، حتى يفصل له العلماء ما وقع فيه، يتصل ببعض العلماء هناك أهل الفقه، من القضاة، ونحوهم من أهل العلم، أهل البصيرة، فيخبرهم بكل ما وقع منه، حتى يكون على بينه، وعلى بصيرة في فتواه، وفيما يراه أهل العلم -إن شاء الله- البركة والخير، وقد بيَّنا له ما يلزم حسب ما قد عرفنا من سؤاله. المقدم: ماذا عن مظاهرته، التي يقول: تكوني مثل أمي وأختي؟ الشيخ: هذا عليه كفارة الظهار، عليه أن يكفر إذا كان يستطيع الصيام، يصوم شهرين متتابعين، فإن كان ما يستطيع الصيام؛ يطعم ستين مسكينًا، عليه أن يطعم ستين مسكينًا.\nالمقدم: هو حسب سؤاله يقول: ذكر هذا الكلام مرتين، في المرة الأولى يقول: سألت عنه وكفرت بإطعام ستين مسكينًا، وقيل لي: لك طلقة.\nالشيخ: تجزئه، إذا كان لا يستطيع الصيام، يجزيه إطعام ستين مسكينًا، إذا كان لا يستطيع الصيام، ويقع عليها طلقة إذا كان ما أراد منعها، إنما أراد إيقاع الطلاق يكون عليه طلقة، أما إن كان أراد منعها، وكفها عن هذا الشيء، ولم يرد إيقاع الطلاق، وإنما أراد تخويفها، وتحذيرها، وكفها عن ذلك؛ فإن عليه كفارة يمين. المقدم: حتى في الظهار؟ الشيخ: مع كفارة الظهار، عن الطلقة يعني، عن الطلقة التي أوقعها، نعم. المقدم: إذًا معنى هذا بقي عليه كفارة ظهار واحدة؛ لأنه ذكر أنه ظاهر مرتين. الشيخ: نعم، نعم، وكفارة اليمين عن الطلقة إذا كان أراد منعها وكفها، نعم.","link":"https://binbaz.org.sa/fatwas/13832/مساىل-في-الحلف-بالحرام-والطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_683/nour_68302.mp3","categories":["الطلاق","الظهار"]},{"id":15331,"question":"هذه أول رسالة في حلقتنا اليوم، من المستمع: حسين علي محمد اليماني، مقيم بالرياض، يقول: حصل بيني وبين زوجتي خصام، فاشتد غضبي، فقلت لها: جعلتك كمثل أمي وكرائمي، وقد سألت بعض العلماء في ذلك، فقالوا: يجب عليك كفارة ظهار، ولكني لم أستطع فعل شيء منها، فقد أطعمت ستة مساكين، فقط، ثم اتصلت بزوجتي بعد ذلك، وهي الآن عندي، فما رأيكم في هذا؟أفيدوني، وفقكم الله.","title":"حكم من جامع أهله قبل الوفاء بكفارة الظهار","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فالقول للمرأة: أنت علي حرام، أو مثل أمي، أو مثل أختي.. أو نحو ذلك، هذا أمر لا يجوز، لأن الله -جل وعلا- حرم المظاهرة منها، وتشبيهها بالأم، أو بالأخت، وذكر سبحانه أنه منكر من القول، وزور، فلا يجوز للمسلم أن يقول لزوجته: أنت مثل أمي، أو أنت حرام علي كأمي، أو كأختي، أو كظهر أمي، كل هذا لا يجوز، والواجب عليه أن يحفظ لسانه عن مثل هذا، والله سبحانه قال: وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا[المجادلة:3] الآية، فبيَّن -جل وعلا- أن المظاهر له أحكام، فيجب على المؤمن أن يتقيد بحكم الله -جل وعلا-، ولا يتساهل في الأحكام. فإذا قال هذا الكلام، وأحب الرجوع إليها، والعود إليها؛ فإن عليه كفارة بينها ربنا  في قوله : وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا فَتَحْرِيرُ رَقَبَةٍ مِنْ قَبْلِ أَنْ يَتَمَاسَّا ذَلِكُمْ تُوعَظُونَ بِهِ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ ۝ فَمَنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِنْ قَبْلِ أَنْ يَتَمَاسَّا فَمَنْ لَمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًا ذَلِكَ لِتُؤْمِنُوا بِاللَّهِ وَرَسُولِهِ[المجادلة:3-4] . فالمؤمن يتقيد بحكم الله ورسوله، ولا يعجل، ولا يتساهل، وإذا حصل غضب أو مشاجرة؛ فالواجب عليه أن يتثبت في الأمور، ويتعوذ بالله من الشيطان، ولا يعجل في أمرٍ يضره، فإن الإقدام على ما حرم الله من جملة المعاصي التي تضر العبد، وتسبب غضب الله عليه ، والطلاق كذلك قد يفضي به إلى ما لا تحمد عقباه، فلا يعجل في الطلاق، بل ينبغي له التثبت في الأمور، وعدم العجلة، وأن يتعوذ بالله من الشيطان عند حدوث النزاع، والخصام. وهذا الرجل الذي حرم زوجته يلزمه عتق رقبة، يعني: إما عبد، وإما أمة، فإذا لم يتيسر ذلك؛ فإنه يصوم شهرين متتابعين، قبل أن يتصل بها -قبل أن يجامعها- فإن عجز عن ذلك أطعم ستين مسكينًا، لا ستة، بل عليه أن يطعم ستين مسكينًا، كما أمر الله بهذا ، وإطعامهم؛ بكونه يعشيهم، أو يغديهم، أو يعطي كل واحد نصف صاع من قوت البلد من تمر، أو أرز، أو حنطة، أو ذرة، من قوت بلده، قبل أن يمسها، وهذا معنى: مِنْ قَبْلِ أَنْ يَتَمَاسَّا[المجادلة:4] يعني: من قبل أن يتصل بها ويجامعها. والسائل قد أخطأ في جماعه لها قبل أن يكمل الكفارة، فعليك -أيها السائل- أن تمتنع منها، وأن تكف عن جماعها؛ حتى تكفر الكفارة الواجبة، وإذا كنت لا تستطيع صيام شهرين متتابعين؛ فإنك تكمل الإطعام، أطعمت ستة، بقي عليك أربعة وخمسون، عليك أن تطعم أربعة وخمسين مسكينًا، مع الستة حتى يكون الجميع ستين مسكينًا، تعطي كل واحد نصف صاع، وهو كيلو ونصف تقريبًا من الحنطة، أو من التمر، أو من الأرز، أو من قوت بلدك، إن كان بلدك عندكم فيه الذرة، فمن الذرة، حتى تكمل الستين، ومقدار هذا بالوزن كيلو ونصف تقريبًا، فإذا كملت ذلك؛ جاز لك أن تأتيها، وعليك التوبة إلى الله مما فعلت، عليك التوبة إلى الله سبحانه من قربانك إياها، عليك التوبة إلى الله ، فإن قربانك إياها قبل الكفارة؛ معصية، فعليك أن تتوب إلى الله  من ذلك، وعليك أن تكمل الكفارة بإطعام أربعة وخمسين مسكينًا، كل واحد يعطى نصف الصاع من التمر، أو غيره من قوت البلد، هذا إذا كنت لا تستطيع الصيام، وبعد هذا كله تحل لك زوجتك، وعليك التوبة إلى الله، والندم على ما فعلت، والاستغفار، كسائر الذنوب، نعم.\nالمقدم: لو أراد أن يطعمهم كما تفضلتم بأن يغديهم، أو يعشيهم فهل يجوز له أن يطعمهم على دفعات مثلًا؟\nالشيخ: ما في بأس، لا حرج أن يفرقهم.\nالمقدم: ليس بلازم، ما هو بلازم أن يطعمهم دفعة واحدة؟ الشيخ: ما هو بلازم أن يجمعهم جميعًا لو غدى هؤلاء في وقت عشرة، وعشرين في وقت آخر، أو خمسة، أو ستة حتى يكملهم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13825/حكم-من-جامع-اهله-قبل-الوفاء-بكفارة-الظهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_683/nour_68301.mp3","categories":["الطلاق","الظهار"]},{"id":15418,"question":"سؤاله الآخر يقول: قبل سنتين تشاجرت أنا وزوجتي، فقلت لها عدة مرات وأنا في حالة غضب: أنت مثل أمي، وبعدها بثلاثة أيام تصالحنا دون أن يعلم أحد بمشاجرتنا مطلقًا، إلا الله ، فهل علينا إثم في ذلك أو كفارة؟","title":"حكم من قال لزوجته في حالة غضب: أنت مثل أمي","answer":"الجواب: عليك التوبة إلى الله؛ لأن الظهار منكر من القول وزور، كما قال الله : وَإِنَّهُمْ لَيَقُولُونَ مُنْكَرًا مِنَ الْقَوْلِ وَزُورًا[المجادلة:2] فالظهار لا يجوز، فالله سبحانه أباح الزوجة، ولم يحرمها، فجعلها كظهر أمك وأختك من المنكرات، فعليك التوبة إلى الله سبحانه من ذلك، وعليك كفارة الظهار، وهي عتق رقبة مؤمنة، فإن لم تستطع فصيام شهرين متتابعين، فإن لم تستطع فإطعام ستين مسكينًا قبل أن تمسها، هذا هو الواجب؛ لقوله : وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا فَتَحْرِيرُ رَقَبَةٍ مِنْ قَبْلِ أَنْ يَتَمَاسَّا..[المجادلة:3] الآيات. فعليك أن تعتق رقبة إن وجدت ذلك، فإن لم يتيسر ذلك، فعليك صيام شهرين متتابعين، فإن لم تستطع فعليك أن تطعم ستين مسكينًا، ثلاثين صاعًا من قوت البلد كل واحد يعطى نصف الصاع من قوت البلد، وهو كيلو ونصف تقريبًا من رز أو تمر أو حنطة، أو نحو ذلك، من قوت البلد، قبل أن تمسها، مع التوبة إلى الله، والاستغفار والندم على ما حصل منك، والله -جل وعلا- يتوب على التائبين إذا صدقوا في التوبة، نعم.\nالمقدم: وبالنسبة لما حصل منه قبل أن يعلم بهذا الحكم؟ الشيخ: عليه التوبة إلى الله، والامتناع والتوقف حتى يكفر هذه الكفارة، نعم.","link":"https://binbaz.org.sa/fatwas/13936/حكم-من-قال-لزوجته-في-حالة-غضب-انت-مثل-امي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_685/nour_68502.mp3","categories":["الطلاق","الظهار"]},{"id":15435,"question":"هذا سؤال من المستمع (س. م. س) من الطائف يقول: ذهبت زوجتي إلى بيت أحد الجيران، فقررت أن أطلقها بسبب ذهابها بدون إذن مني، فقلت لها: خذي جميع ما يخصك في هذا المنزل، وأنا محرمك، ولكن والديَّ الاثنين قالا لي: أنت الذي تخرج، وهي تجلس معنا، وأجبروني على عدم تنفيذ كلامي.علمًا أنني لم ألفظ بالطلاق، ولكن قلت لها: أنا محرمك، وقد سألت بعض الناس فقالوا لي: هذا لا يعتبر طلاقًا، وليس له كفارة، أفيدوني -جزاكم الله خيرًا- بالقول الصحيح في هذا الموضوع.","title":"حكم من قال لزوجته: أنا محرمك","answer":"الجواب: إذا كان الأمر كما قاله السائل، فإن عليك كفارة الظهار عن قولك: أنا محرمك، كما لو قلت على: أنت علي كظهر أمي، فعليك كفارة الظهار إذا كنت ما أردت الطلاق بهذا، ما نويت الطلاق بهذا، فهذا حكمه حكم الظهار في أصح أقوال أهل العلم. فعليك كفارة الظهار، وهي عتق رقبة مؤمنة، فإن لم تجد صمت شهرين متتابعين، فإن شق عليك ذلك، ولم تستطع أطعمت ستين مسكينًا ستين فقيرًا، تعطي كل واحد نصف صاع من التمر، أو من الأرز، أو من الحنطة، أو من قوت بلدك إن كان قوت بلدك الذرة، أو الدخن، كذلك مقدار كيلو ونص تقريبًا؛ لكل واحد من الستين قبل أن تمسها قبل أن تجامعها، هذا هو الواجب عليك إذا كنت ما أردت الطلاق. أما إذا كنت أردت الطلاق بـ: أنا محرمك، يعني: قصدك طلاقها فهذا على الصحيح طلقة واحدة، يكون حكمه حكم الطلقة الواحدة، فإذا كان ما قبلها طلقتين ليس قبله طلقتان فلك أن تراجعها بأن تقول: راجعت امرأتي أو أنا مراجع امرأتي، أو رددت امرأتي أو نحو ذلك بإشهاد اثنين، تشهد رجلين عدلين بأنك راجعتها، وتحل لك ما دامت في العدة.\nالمقدم: حتى لو كررها بنية الطلاق؟ لو كرر هذه الكلمات؟\nالشيخ: المقصود: ما دام قالها مرة بنية الطلاق يكون طلقةً واحدة، إذا كان ما سبقها طلقتان يراجعها، أما إن كان سبقها طلقتان تكون هذه الثالثة ما فيها رجعة إلا بعد زوج.\nأما إن كررها قال: محرمك محرمك محرمك، قصده الطلاق الثلاث تكون ثلاثًا، وإن كررها لأجل إفهامها، أو لأجل تأكيد الكلام، فلا يكون إلا طلقة واحدة، إذا كان نوى الطلاق، وأما إذا كان ما نوى الطلاق فهو ظهار، وإن كرر مائة مرة هو ظهار فيه كفارة واحدة فقط. والظهار هو أن يقول: أنت علي كظهر أمي، أنت علي محرمة، أنت علي كأختي، هذا يكون ظهار فيه كفارة الظهار كما تقدم، وهي عتق رقبة مؤمنة، فإن لم يتيسر هذا صام شهرين متتابعين ستين يومًا، فإن عجز أطعم ستين مسكينًا، ثلاثين صاعًا الصاع ثلاثة كيلو تقريبًا، يعطي كل واحد كيلو ونصف تقريبًا من قوت بلده من حنطة من أرز من تمر من ذرة، يكفي ستين فقيرًا، ثلاثين صاعًا، فالصاع مقدار ثلاثة كيلو تقريبًا بين اثنين لكل واحد نصف الصاع كيلو ونصف تقريبًا قبل أن يمسها، هذا إذا ما أراد الطلاق، أما إذا كان أراد بقوله: محرمك الطلاق، فالصواب: أنه يكون طلاقًا يكون طلقة واحدة، ولو كررها بنية التأكيد أو نية الإفهام تكون واحدة.\nأما إذا ما أراد الطلاق، وإنما أراد تحريمها، أو ما أراد شيئًا فيكون فيه كفارة الظهار، نعم. المقدم: لو فرض أنه سيكفر عن الظهار بصيام، ولكنه بعد أن صام عدة أيام طرأ له مرض مما يسبب له عجزًا عن إتمام الصيام، فهل يجوز له أن يعدل إلى الإطعام؟\nالشيخ: يبني على ما مضى، إذا شفي يبني على ما مضى يكمل الستين اليوم.\nالمقدم: لا يجوز أن يعدل إلى الإطعام بعد أن بدأ...؟\nالشيخ: لا، إذا كان مرضًا يرجى برؤه، لا يعجل، إذا شفي يبدأ بالحال؛ لأنه قادر على الصيام، هذا مرض عارض، أما إذا كان مرضًا يعني: لا يرجى برؤه، أو شيخًا كبيرًا عاجزًا أو امرأةً أو شيخًا كبيرًا عاجزًا، فهذا عليه الإطعام فقط؛ لأنه عاجزـ أو عنده أعمال كثيرة شاقة يتكسب، أو في عمل يشق عليه الصيام معه أجزأه الانتقال إلى الإطعام، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13968/حكم-من-قال-لزوجته-انا-محرمك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_686/nour_68604.mp3","categories":["الطلاق","الظهار"]},{"id":15488,"question":"هذا سؤال من المستمع: (ق. ع. أ) من بلاد زهران، قلوة، يقول: أنا رجل متزوج، وقد حصلت خصومة ذات يوم مع زوجتي، فطلبت منها فعل شيء، ولكنها رفضت، فكررت عليها وهي مصرة على رفضها، فقلت لها: لو رفضت فأنت محرمة علي كما حرمت علي أمي، ولكنها أصرت على رفضها، ثم استمرت حياتنا الزوجية بعد ذلك دون أن أكفر. علمًا أنني كثيرًا ما أحلف بالطلاق على أشياء وأحنث في يميني ولا أكفر، ولكني لا أقصد الطلاق، وإنما نتيجة الغضب والحماقة، والآن لي مع زوجتي أربع سنين، ولي منها طفلان، فماذا علي الآن؟أفيدوني، وفقكم الله.","title":"حكم التلفظ بالحرام والطلاق بنية التخويف","answer":"الجواب: أولًا: لا ينبغي تعاطي هذه الأمور، ينبغي لك -أخي- ألا تتعاطى هذه الأمور، لا التحريم ولا الطلاق، بل تخاطبها بغير ذلك، وتأمرها وتنهاها بغير ذلك، وينبغي أن تنزه نفسك ولسانك عن هذا حتى لا تقع في مشاكل، وفي أمور قد تحرم عليك زوجتك وأنت لا تشعر، فعليك أن تجتنب هذه الألفاظ تمامًا. أما حكم ما وقع فإذا كان الواقع منك بقصد التخويف، وحثها على أن تعمل ما قلت لها، وليس القصد من ذلك فراقها، فإنه عليك كفارة يمين، وليس عليك طلاق، ولا ظهار، إذا كان المقصود حملها على العمل، وأن تنفذ ما قلت لها، وليس قصدك إيقاع الطلاق وفراقها إن لم تفعل، فإن عليك في هذا كفارة يمين، وإن كفرت كفارة ظهار؛ لأنك قلت: كأمي من باب الاحتياط فحسن، ولكن يكفي هذا كفارة يمين؛ لأن المقصود حملها على ما قلت لها حتى تفعل. وهكذا لو تلفظت بلفظ الطلاق، عليك الطلاق أن تفعلي كذا، أو إن لم تفعلي كذا، فأنت طالق، والمقصود حملها على الفعل، وحثها، وتخويفها، فهذا كله ليس فيه إلا كفارة يمين، وهي إطعام عشرة مساكين، أو كسوتهم، والإطعام نصف صاع من التمر أو الرز أو الحنطة كيلو ونصف تقريبًا من قوت البلد، والكسوة إزار ورداء أو قميص يستر في الصلاة هذه الكسوة، أو عتق عبد أو عبدة، تحرير عبد أو عبدة، هذه هي الكفارة، فإن عجزت عن هذا كله، كفاك صيام ثلاثة أيام، كما نص عليه كتاب الله في سورة المائدة في كفارة اليمين. لكن بكل حال ننصحك أن تحذر هذه الألفاظ، وتحذر التساهل بها دائمًا، وعليك أن تبادر بالكفارة عما فعلت، كفارة الأيمان عما فعلت سابقًا، عن كل واحدة تطعم عشرة مساكين، خمسة أصواع من التمر، أو الرز أو الحنطة، كل واحد له نصف الصاع، يعني: كيلو ونصف من هذه الأطعمة، أو تكسو عشرة بإزار ورداء، أو بقميص كفارة يمينك؛ لأن هذه الأشياء في حكم اليمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14024/حكم-التلفظ-بالحرام-والطلاق-بنية-التخويف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_690/nour_69004.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":15579,"question":"هذا سؤال من المستمع (ج. ج. ق) من المغرب فاس، يقول: أحيانًا أقول: زوجتي طالق علي أو حرام أن لا أفعل ذلك الشيء، ثم تغريني نفسي وأفعله، والآن أريد أن أتوب إلى الله توبة خالصة.أفيدوني، جزاكم الله خيرًا، ما الحل في قولي هل يقع الطلاق، أم علي كفارة، أم علي صيام؟","title":"حلف بالطلاق وقال: حرام علي إن فعلت كذا وفعل؛ فما الحكم؟","answer":"الجواب: إذا قلت ذلك فالحكم يختلف بحسب النية؛ لأن الرسول ﷺ قال: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى فإذا قلت: علي الطلاق أني لا أفعل كذا، أو حرام علي أن لا أفعل كذا، فإن كنت أردت إيقاع الطلاق بهذا، فإنه يقع الطلاق طلقة واحدة، وإذا كررت ذلك وقع ما كررته من ثنتين أو ثلاث. أما إن كنت ما أردت الطلاق، وإنما أردت المنع، منع نفسك من هذا الشيء، لم ترد الطلاق، وإنما أردت أن تمنع نفسك، كأن تقول: علي الطلاق لا أزور فلانًا، علي الطلاق لا أكلم فلانًا، تريد منع نفسك من هذا الشيء، ولم ترد إيقاع الطلاق، فإن عليك كفارة يمين، ولا يقع الطلاق، وكفارة اليمين إطعام عشرة مساكين، أو كسوتهم، إما أن تطعمهم غداءً أو عشاءً، أو نصف صاع من قوت البلد كيلو ونصف من قوت البلد، لكل واحد تمر أو رز أو نحو ذلك، وإما أن تكسوهم كسوة قميص لكل واحد أو إزار ورداء لكل واحد، والعاجز الفقير الذي لا يستطيع هذه الأشياء يصوم ثلاثة أيام، كما دل عليه كتاب الله . وهكذا الحرام إذا قلت: علي الحرام ما أفعل كذا، فإذا أردت أنك تحرمها إن فعلته، وأنها حرام عليك إن فعلته، كان ظهارًا فيه كفارة الظهار إذا فعلت هذا الشيء وهي عتق رقبة مؤمنة، فإن عجزت صمت شهرين متتابعين، فإن عجزت أطعمت ستين مسكينًا، ثلاثين صاعًا، توزع بينهم لكل واحد نصف صاع من قوت البلد من تمر أو رز أو حنطة ونحو ذلك، هذا إذا كنت أردت التحريم تحريمها عليك إن فعلت. أما إن كنت أردت المنع منع نفسك من هذا الشيء كأن تقول: علي الحرام ما أكلم فلانًا، أو علي الحرام ما أزور فلانًا، فإن هذا حكمه حكم اليمين كما تقدم، فعليك كفارة يمين؛ لقوله تعالى: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝  قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ[التحريم:2] فسمى التحريم يمينًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14120/حلف-بالطلاق-وقال-حرام-علي-ان-فعلت-كذا-وفعل-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_692/nour_69205.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":15658,"question":"سؤاله الثاني يقول: أثناء إقامتي في بلدي حلفت على زوجتي: لو ذهبت إلى المكان الفلاني تكوني محرمة علي، ووقت بقائي هناك لم تذهب، ولكن الآن في غيابي لو ذهبت فما الحكم؟ وعلى من يكون الإثم؟ وماذا أفعل لو ذهبت وأنا لم أعلم بذلك؟","title":"حكم من قال لزوجته: أنت محرمة علي لو ذهبت إلى كذا","answer":"الجواب: إذا لم تعلم فالإثم عليها؛ لأن عليها السمع والطاعة، وعدم الخروج إلى المحل الذي منعتها منه إلا بأمر شرعي، ومسوغ شرعي، فإذا خرجت ولم تعلم فإن الإثم عليها، أما إذا علمت ففيه تفصيل:\nإن كنت أردت بهذا تحريمها إن فعلت هذا الشيء فعليك كفارة الظهار.\nوإن كنت أردت منعها فقط، أردت أن تمنعها من هذا الشيء لا تحريمها، فعليك كفارة اليمين: إطعام عشرة مساكين، أو كسوتهم، عشرة، يطعمهم على كل واحد يعطى كل واحد نصف صاع من التمر من قوت البلد من التمر، أو من الأرز، أو من الحنطة، أو من الذرة، إن كان قوت البلد، ويكفي عشرة، كل واحد يعطى نصف صاع، يعني: كيلو ونصف تقريبًا؛ لأن حكمها حكم اليمين، إذا كان يعني قال: هي محرمة إن فعلت كذا وكذا، إذا كان المقصود المنع وليس المقصود تحريمها تحريم الظهار، فإن عليه كفارة اليمين، وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد، مقداره كيلو ونصف تقريبًاً، أو كسوتهم على قميص قميص، أو إزار ورداء. أما إن كان المقصود تحريمها تحريم الظهار، تكون حرام عليه إذا فعلت، فعليه كفارة الظهار، وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين، فإن لم يستطع أطعم ستين مسكينًا، ثلاثين صاعًا، كل مسكين له نصف الصاع، كيلو ونصف تقريبًا، قبل أن يمسها إذا كان قصده تحريمها، قبل أن يمسها. أما إن كان قصد بهذا الطلاق، أنها متى فعلت تطلق، فهذا يقع به طلقة واحدة، إذا كان قصده الطلاق، وأنها متى فعلت تطلق، يقع به واحدة، أما إن كان أراد المنع لم يرد طلاقًا ولا تحريمًا، وإنما أراد المنع فعليه كفارة اليمين فقط كما تقدم، نعم.\nالمقدم: لو فعلت ذلك وكان يقصد الطلاق فعلًا فتكون طالقًا من وقت الفعل أو من وقت؟\nالشيخ: إذا كان أراد الطلاق، إذا كان أراد إيقاع الطلاق تكون طالقة من وقت الفعل. المقدم: من وقت الفعل؟\nالشيخ: أما إذا كان أراد منعها فقط وتخويفها، ولم يرد منعها، ولا تحريمها، هذا فيه كفارة يمين، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14203/حكم-من-قال-لزوجته-انت-محرمة-علي-لو-ذهبت-الى-كذا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_699/nour_69909.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":15738,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: مقيم في المملكة (ص. ع. أ) يبدو من خطه أنه سوداني، يسأل تفسير قول الحق -تبارك وتعالى-: وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا فَتَحْرِيرُ رَقَبَةٍ مِنْ قَبْلِ أَنْ يَتَمَاسَّا ذَلِكُمْ تُوعَظُونَ بِهِ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ [المجادلة:3] صدق الله العظيم.","title":"تفسير قوله تعالى: {وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ...}","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فهذه الآية الكريمة تبين حكم الظهار، والمظاهرة معناها: أن يقول: زوجته كظهر أمه، أنت عليّ كظهر أمي، أو كظهر أختي، أو ظهر خالتي، أو ما أشبه ذلك، وهذه تسمى ظهار، والله أوجب فيه سبحانه الكفارة إذا عاد إلى زوجته بالعزم، إذا عزم أن يعود وجب عليه كفارة قبل أن يعود قَبْلِ أَنْ يَتَمَاسَّا[المجادلة: 3] وهي عتق رقبة مؤمنة ذكر أو أنثى، فإن عجز صام شهرين متتابعين، ستين يومًا قبل أن يمسها، فإن عجز أطعم ستين مسكينًا، لكل مسكين نصف صاع، من صاع النبي -عليه الصلاة والسلام-، مقداره كيلو ونصف تقريبًا من قوت البلد تمر أو رز أو حنطة من شعير أو قوت البلد قبل أن يمسها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14318/تفسير-قوله-تعالى-والذين-يظاهرون-من-نساىهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74101.mp3","categories":["الطلاق","الظهار","الرجعة"]},{"id":15977,"question":"هذا سؤال من السائل (ع. ط. أ. هـ) من الرياض، يقول: أنا رجل متزوج، وقد غضبت من فعل فعلته زوجتي فلم أتمالك نفسي ثم قلت لها: أنت علي كظهر أمي، ثم كررت ذلك مرات ومرات، وطردتها إلى بيت أبيها لمدة ثلاثة أشهر، وبعد مضي هذه المدة راجعتها لفرط حبي لها، وقد أنجبت أربعة أطفال منذ رجوعها، وإلى اليوم ما زلت أذكر ذلك الموقف المشؤوم، علمًا بأني لم أكفر عن ظهاري طيلة هذه المدة.ثم نقلت من مقر عملي القديم إلى مدينة بعيدة عن موطني، ومقر أهلي، فتركت هذه الزوجة هي ووالدتي وأولادي منها، ثم قضيت تسعة أشهر بعيدًا عنهم، وبعد هذه المدة رجعت إليهم في عطلة سنوية وعند وصولي إليهم، وسؤالي عن أحوالهم، وطريقة حياتهم في مدة غيابي أجابني ابني الأكبر بأن فلانًا من الناس يقيم عندنا في بيتنا، علمًا بأن هذا الرجل المذكور واحدًا من أقارب زوجتي، ولكنه ليس من محارمها، ولا حتى ممن كانوا يزورون بيتي طيلة فترة وجودي، وعندما علمت ذلك من ابني سألت زوجتي عن سبب مجيء ذلك الرجل ليقيم في بيتي، وأنا غائب عنه، ودون إذني، فأجابت إجابة واهية تقول فيها: طلب مني ذلك، فاستحيت أن أمنعه؛ لأنه أحد أقاربي، وأنا أشك في صحة مقصدها في تصرفها الأول والثاني، وليس عندي ما يؤكد صدق ظنوني فيها، وعمومًا أطلب منكم رأيكم من الناحية الشرعية؛ لأنني لا أريد أن أتصرف إلا وفق الشريعة الإسلامية التي تحمي زوجتي مني، وتحميني منها، فهل أطلقها، وأشرد أولادي وبناتي أم أبقيها هي وأولادها وأتزوج غيرها أم أصبر معها حتى يأتي الله بالفرج؟علمًا بأنني أستطيع أن أعول أكثر من امرأة. وما الحكم في ظهاري الأول الذي أرجعتها بعده دون كفارة؟أفيدوني، جزاكم الله خيرًا.","title":"حكم الجماع قبل كفارة الظهار والخلوة بالأجنبية","answer":"الجواب: أولًا: ردك إياها وجماعك إياها بعد الظهار قبل الكفارة هذا منكر ومحرم، وقد عصيت الله في ذلك؛ لأن الله سبحانه إنما أباح لك ذلك بعد الكفارة، فعليك أن تتوب إلى الله  وأن تبادر بالكفارة قبل أن تقربها عليك أن تمسك عن قربانها حتى تبادر بالكفارة، وهي عتق رقبة مؤمنة، فإن لم تجد فصيام شهرين متتابعين، فإن لم يستطع فإطعام ستين مسكينًا، ثلاثين صاعًا قبل أن تقربها، وعليك التوبة إلى الله -جل وعلا- والندم على ما مضى منك، والإقلاع من ذلك، والعزم ألا تعود في ذلك عزمًا صادقًا، هذا هو الواجب عليك من جهة الظهار، فإذا كنت لا تستطيع العتق ولا الصيام فعليك أن تطعم ستين مسكينًا، ستين فقيرًا ثلاثين صاعًا من التمر أو من الحنطة أو من الأرز لكل مسكين نصف صاع، مقدار كيلو ونصف تقريبًا، هذا هو الواجب عليك، وعليك أن تمسك عن جماعها حتى تخرج هذه الكفارة، الصيام إن قدرت أو الإطعام بعد ذلك، فهي مرتبة: أولًا العتق، ثم الصيام إن قدرت، ثم الإطعام فهو الأخير الإطعام، ستين مسكينًا ستين فقيرًا ثلاثين صاعًا من الحنطة أو التمر أو الأرز تفرقها عليهم، كل واحد له نصف الصاع؛ كيلو ونصف بالوزن. أما هذا الرجل الذي صار إلى البيت فلا شك أن هذا منكر، ويوجب الريبة، وهي قد أخطأت، وكذلك أهلك حين أقروها على هذا، أمك وأهلك الذين أقروها على بقائه في البيت، لكن إذا كانت هناك أسباب وجيهة لوجوده في البيت من حاجة، وعدم وجود مكان له يستقر فيه، والوالدة وأهلك قد رضوا بهذا لأجل ..... يأكل عندهم، وليس هناك ريبة، فالحمد لله.  أما إن كان هناك ريبة فإن الواجب طرده من البيت، والواجب توبيخها أيضًا، والإنكار عليها، ولا مانع من تأديبها التأديب المناسب الذي لا يجرح ولا يكسر، لا يجرح لحمًا ولا يكسر عظمًا، حتى لا تعود لمثل هذا، وزوجتك باقية في عصمتك. وإن كانت ألمت بشيء فعليها التوبة إلى الله فيما بينها وبين الله، والتوبة تجب ما قبلها، وهي زوجتك، وعليك ملاحظتها، وتوصي أهلك بملاحظتها، وعليك أن تنصحها كثيرًا، وتخوفها من الله ، وتعلمها أن الخلوة بالرجل الأجنبي أمر محرم، وعدم الحجاب عن الأجنبي أمر محرم، والزنا من أقبح الكبائر، وأعظم السيئات، فعليك أن تنصحها وتوجهها إلى الخير، وتعلمها ما ينفعها، وتوصي أهلك بذلك، وتوصي أهلها بذلك أيضًا، ولعل الله -جل وعلا- يهديها ويوفقها فتصلح الأحوال بينك وبينها، ونسأل الله لنا ولكم الهداية والتوفيق، نعم.\nالمقدم: لو حصل أولاد خلال هذه العشرة المحرمة بعد الظهار، وقبل أن يكفر، فما الحكم؟\nالجواب: هذا شيء آخر يسأل عنه أهل العلم إذا وقع شيء، يسأل أهل العلم القضاة في بلده، أو يكتب إلينا في ذلك، لا نستعجل في هذا، نعم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/14593/حكم-الجماع-قبل-كفارة-الظهار-والخلوة-بالاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_679/nour_67902.mp3","categories":["الطلاق","الظهار"]},{"id":15981,"question":"هذا سؤال من السائل (ع. ط. أ. هـ) من الرياض، يقول: أنا رجل متزوج، وقد غضبت من فعل فعلته زوجتي فلم أتمالك نفسي ثم قلت لها: أنت علي كظهر أمي، ثم كررت ذلك مرات ومرات، وطردتها إلى بيت أبيها لمدة ثلاثة أشهر، وبعد مضي هذه المدة راجعتها لفرط حبي لها، وقد أنجبت أربعة أطفال منذ رجوعها، وإلى اليوم ما زلت أذكر ذلك الموقف المشؤوم، علمًا بأني لم أكفر عن ظهاري طيلة هذه المدة.ثم نقلت من مقر عملي القديم إلى مدينة بعيدة عن موطني، ومقر أهلي، فتركت هذه الزوجة هي ووالدتي وأولادي منها، ثم قضيت تسعة أشهر بعيدًا عنهم، وبعد هذه المدة رجعت إليهم في عطلة سنوية وعند وصولي إليهم، وسؤالي عن أحوالهم، وطريقة حياتهم في مدة غيابي أجابني ابني الأكبر بأن فلانًا من الناس يقيم عندنا في بيتنا، علمًا بأن هذا الرجل المذكور واحدًا من أقارب زوجتي، ولكنه ليس من محارمها، ولا حتى ممن كانوا يزورون بيتي طيلة فترة وجودي، وعندما علمت ذلك من ابني سألت زوجتي عن سبب مجيء ذلك الرجل ليقيم في بيتي، وأنا غائب عنه، ودون إذني، فأجابت إجابة واهية تقول فيها: طلب مني ذلك، فاستحيت أن أمنعه؛ لأنه أحد أقاربي، وأنا أشك في صحة مقصدها في تصرفها الأول والثاني، وليس عندي ما يؤكد صدق ظنوني فيها، وعمومًا أطلب منكم رأيكم من الناحية الشرعية؛ لأنني لا أريد أن أتصرف إلا وفق الشريعة الإسلامية التي تحمي زوجتي مني، وتحميني منها، فهل أطلقها، وأشرد أولادي وبناتي أم أبقيها هي وأولادها وأتزوج غيرها أم أصبر معها حتى يأتي الله بالفرج؟علمًا بأنني أستطيع أن أعول أكثر من امرأة. وما الحكم في ظهاري الأول الذي أرجعتها بعده دون كفارة؟أفيدوني، جزاكم الله خيرًا.","title":"حكم الجماع قبل كفارة الظهار والخلوة بالأجنبية","answer":"الجواب: أولًا: ردك إياها وجماعك إياها بعد الظهار قبل الكفارة هذا منكر ومحرم، وقد عصيت الله في ذلك؛ لأن الله سبحانه إنما أباح لك ذلك بعد الكفارة، فعليك أن تتوب إلى الله  وأن تبادر بالكفارة قبل أن تقربها عليك أن تمسك عن قربانها حتى تبادر بالكفارة، وهي عتق رقبة مؤمنة، فإن لم تجد فصيام شهرين متتابعين، فإن لم يستطع فإطعام ستين مسكينًا، ثلاثين صاعًا قبل أن تقربها، وعليك التوبة إلى الله -جل وعلا- والندم على ما مضى منك، والإقلاع من ذلك، والعزم ألا تعود في ذلك عزمًا صادقًا، هذا هو الواجب عليك من جهة الظهار، فإذا كنت لا تستطيع العتق ولا الصيام فعليك أن تطعم ستين مسكينًا، ستين فقيرًا ثلاثين صاعًا من التمر أو من الحنطة أو من الأرز لكل مسكين نصف صاع، مقدار كيلو ونصف تقريبًا، هذا هو الواجب عليك، وعليك أن تمسك عن جماعها حتى تخرج هذه الكفارة، الصيام إن قدرت أو الإطعام بعد ذلك، فهي مرتبة: أولًا العتق، ثم الصيام إن قدرت، ثم الإطعام فهو الأخير الإطعام، ستين مسكينًا ستين فقيرًا ثلاثين صاعًا من الحنطة أو التمر أو الأرز تفرقها عليهم، كل واحد له نصف الصاع؛ كيلو ونصف بالوزن. أما هذا الرجل الذي صار إلى البيت فلا شك أن هذا منكر، ويوجب الريبة، وهي قد أخطأت، وكذلك أهلك حين أقروها على هذا، أمك وأهلك الذين أقروها على بقائه في البيت، لكن إذا كانت هناك أسباب وجيهة لوجوده في البيت من حاجة، وعدم وجود مكان له يستقر فيه، والوالدة وأهلك قد رضوا بهذا لأجل ..... يأكل عندهم، وليس هناك ريبة، فالحمد لله.  أما إن كان هناك ريبة فإن الواجب طرده من البيت، والواجب توبيخها أيضًا، والإنكار عليها، ولا مانع من تأديبها التأديب المناسب الذي لا يجرح ولا يكسر، لا يجرح لحمًا ولا يكسر عظمًا، حتى لا تعود لمثل هذا، وزوجتك باقية في عصمتك. وإن كانت ألمت بشيء فعليها التوبة إلى الله فيما بينها وبين الله، والتوبة تجب ما قبلها، وهي زوجتك، وعليك ملاحظتها، وتوصي أهلك بملاحظتها، وعليك أن تنصحها كثيرًا، وتخوفها من الله ، وتعلمها أن الخلوة بالرجل الأجنبي أمر محرم، وعدم الحجاب عن الأجنبي أمر محرم، والزنا من أقبح الكبائر، وأعظم السيئات، فعليك أن تنصحها وتوجهها إلى الخير، وتعلمها ما ينفعها، وتوصي أهلك بذلك، وتوصي أهلها بذلك أيضًا، ولعل الله -جل وعلا- يهديها ويوفقها فتصلح الأحوال بينك وبينها، ونسأل الله لنا ولكم الهداية والتوفيق، نعم.\nالمقدم: لو حصل أولاد خلال هذه العشرة المحرمة بعد الظهار، وقبل أن يكفر، فما الحكم؟\nالجواب: هذا شيء آخر يسأل عنه أهل العلم إذا وقع شيء، يسأل أهل العلم القضاة في بلده، أو يكتب إلينا في ذلك، لا نستعجل في هذا، نعم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/14593/حكم-الجماع-قبل-كفارة-الظهار-والخلوة-بالاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_679/nour_67902.mp3","categories":["الطلاق","الظهار"]},{"id":16144,"question":"يسأل سؤالًا آخر، فيقول: رجل اعتاد الحلف بالحرام، فهو يقول دائمًا: علي الحرام لأفعل كذا، ولا أفعل كذا.. وما أشبه ذلك، هل يؤثر هذا على النكاح؟","title":"حكم الحلف بالحرام وكفارته","answer":"الجواب: هذا حكمه حكم اليمين، إذا قال: علي الحرام ما أكلم فلانًا، علي الحرام، ما آكل كذا، علي الحرام ما أسافر، وما أشبه ذلك هذا حكمه حكم اليمين، فيه كفارة اليمين، لقول الله : يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ  ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:1-2] نزلت في تحريمه العسل، وفي قول آخر: أنه تحريمه مارية، مملوكة له بسبب ما جرى بين أزواجه في ذلك: حفصة وعائشة وزينب في شأن العسل، أو شأن الجارية، حلف وحرم أنه لا يقربها، أو حرم ألا يأكل العسل؛ فأنزل الله الآية المذكورة، وهي قوله سبحانه: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ  ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:1-2] قال ابن عباس: معنى ذلك أن في الحرام كفارة اليمين، وهكذا قال جمع من أهل العلم. إلا إذا قصد تحريم زوجته إذا قصد.. إذا صار في نيته عليه الحرام من زوجته، فهذا فيه كفارة الظهار، المذكورة في سورة المجادلة، وهي عتق رقبة مؤمنة، فإن عجز؛ صام شهرين متتابعين، فإن عجز؛ أطعم ستين مسكينًا ثلاثين صاعًا، قبل أن يقربها، قبل أن يمسها، كل صاع يقسم بين اثنين، كل واحد له نصف الصاع، كيلو ونص كل واحد من التمر أو من الحنطة، ستين مسكينًا، يعطى كل واحد كيلو ونص، تسعين كيلو، ثلاثين صاعًا قبل أن يمسها. أما إذا كان ما قصد الزوجة، جرى على لسانه هكذا، أو قصد الامتناع من هذا الشيء، ولم يقصد الزوجة، فهذا فيه كفارة اليمين كما تقدم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14797/حكم-الحلف-بالحرام-وكفارته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_713/nour_71305.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":16824,"question":"ننتقل بعد هذا إلى المملكة الأردنية الهاشمية عمان، عبر رسالة وصلت إلى البرنامج من المستمع همام العبادي فيما يبدو، الأخ همام له سؤال يقول: أهدى قريب زوجتي لنا هدية، فلما رأيتها قلت: علي الحرام لا تدخل بيتي، فأبقوها عند الجيران، وفي اليوم الثاني أدخلت إلى بيتي، واستعملناها، واستفدنا منها، ما هو كفارة ذلك القول؟ جزاكم الله خيرًا.","title":"حكم من حلف ألا تدخل بيته هدية معينة ثم دخلت","answer":"الجواب: أولًا: هذا لغو لا يجوز، تحريم الحلال لا يجوز، عليك التوبة إلى الله من ذلك. الأمر الثاني: على حسب نيتك، إن كنت قصدت الامتناع منها، ولم تقصد تحريم زوجتك، ولا طلاقها؛ فعليك كفارة يمين، والحمد لله، إطعام عشرة مساكين، أو كسوتهم.. عشرة، كل واحد له نصف الصاع من التمر، أو الرز، أو الحنطة، كيلو ونصف كل واحد. أما إن كنت أردت تحريم الزوجة؛ فعليك كفارة الظهار، وهي عتق رقبة مؤمنة، فإن عجزت؛ تصم شهرين متتابعين، ستين يومًا، فإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا قبل أن تقرب زوجتك، كل صاع بين اثنين، يعني: كل صاع ثلاثة كيلو ... كيلو ونصف من قوت البلد، من تمر، أو غيره، أو حنطة، أو أرز. أما إن كنت أردت الطلاق، أردت أنها إذا دخلت بيتك تكن امرأتك طالقًا؛ فإنه يقع بها طلقة واحدة إذا كنت أردت الطلاق، وتراجعها في الحال، تشهد اثنين من إخوانك الطيبين، تشهدهم أنك راجعت زوجتك. الخلاصة: أن لك في هذا ثلاثة أمور: الأمر الأول: أن تكون أردت الامتناع فقط، فهذا فيه كفارة يمين لما استعملتموها، ودخلت البيت، وهي إطعام عشرة مساكين، أو كسوتهم، عشرة، كل واحد له نصف الصاع، كيلو ونصف، أو كسوة ........ تجزئه في الصلاة. الحال الثاني: أن تكون أردت التحريم، تحريمها عليك، تحريم الزوجة بذلك إن دخلت البيت، فهذا فيه كفارة الظهار، كما بينها الله في سورة المجادلة، وهي: عتق رقبة مؤمنة قبل أن تمس زوجتك، فإن عجزت؛ تصم شهرين متتابعين، ستين يومًا قبل أن تمس زوجتك، فإن لم تقدر -لا هذا ولا هذا- فعليك إطعام ستين مسكينًا، ثلاثين صاعًا كل صاع بين اثنين، ومقدار ذلك تسعين كيلو، كل واحد له كيلو ونصف من قوت البلد، من تمر، أو أرز، أو حنطة، أو ذرة، ونحو ذلك، مع التوبة والاستغفار. الحال الثالث: أن تكون أردت الطلاق، أردت أنها إن دخلت بيتك فهي مطلقة زوجتك، فهذا الكلام يقع به طلقة، ولك مراجعتها في العدة، بشهادة اثنين، تشهد اثنين من أهل السنة، تشهد اثنين أنك راجعتها، إذا كنت ما طلقتها قبل هذا طلقتين، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، إذا أذنتم لي سماحة الشيخ بعرض ما أعرفة عن أحوال الناس في مثل هذا الباب. الشيخ: نعم. المقدم: مثل هذا الباب يغلب عليه أنهم يريدون توفير الهدية للمهدي، بحيث لا يكلف نفسه، فحينئذٍ لا بد لسماحتكم من تعليق وحكم آخر؟ الشيخ: على كل حال هو هذا التفصيل إذا كان أراد الامتناع من قبولها توفيرًا له، ورحمة له، وعدم تكليف له؛ فهو إذا قبلها فيها كفارة اليمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15579/حكم-من-حلف-الا-تدخل-بيته-هدية-معينة-ثم-دخلت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_763/nour_76314.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":17583,"question":"يقول: نعلم أن كفارة الظهار عتق رقبة أو صيام شهرين متتابعين، أو إطعام ستين مسكينًا، والله  يقول في آخر الآية: مِنْ قَبْلِ أَنْ يَتَمَاسَّا [المجادلة:3] إذا حصل المساس قبل الكفارة فما الحكم؟","title":"حكم المساس قبل أداء كفارة الظهار","answer":"الجواب: تلزمه الكفارة، تلزمه الكفارة وتتعين بعدما وطئها تتعين، أما قبل ذلك غير متعينة، متى عزم أتى بها وإن طلقها قبل أن يأتي بها فلا عليه شيء أو ماتت، لكن إذا وطئها لزمت الكفارة، وهي مرتبة ماهي مخيرة، أولًا العتق فإن عجز يصوم شهرين متتابعين، فإن عجز يطعم ستين مسكينًا قبل أن يمسها، على الترتيب كما رتبها الله ، أولًا العتق إذا تيسر، فإن عجز يصوم شهرين متتابعين ستين يومًا، فإن عجز أطعم ستين مسكينًا ثلاثين صاعًا، كل فقير له نصف الصاع قبل أن يمسها. فإذا وطئها استعجل ووطئها وجبت عليه الكفارة وعليه التوبة إلى الله من ذلك؛ لأنه استعجل فعليه التوبة والندم خوفًا من الله  وتعظيمًا له، وتعينت عليه الكفارة حينئذ، إن كان مستطيعًا أعتق وإن كان لا يستطيع صام شهرين متتابعين ستين يومًا، وإن عجز أطعم ستين مسكينًا حتى ولو ماتت حتى ولو طلقها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16534/حكم-المساس-قبل-اداء-كفارة-الظهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84117.mp3","categories":["الطلاق","الظهار"]},{"id":17591,"question":"يقول: نعلم أن كفارة الظهار عتق رقبة أو صيام شهرين متتابعين، أو إطعام ستين مسكينًا، والله  يقول في آخر الآية: مِنْ قَبْلِ أَنْ يَتَمَاسَّا [المجادلة:3] إذا حصل المساس قبل الكفارة فما الحكم؟","title":"حكم المساس قبل أداء كفارة الظهار","answer":"الجواب: تلزمه الكفارة، تلزمه الكفارة وتتعين بعدما وطئها تتعين، أما قبل ذلك غير متعينة، متى عزم أتى بها وإن طلقها قبل أن يأتي بها فلا عليه شيء أو ماتت، لكن إذا وطئها لزمت الكفارة، وهي مرتبة ماهي مخيرة، أولًا العتق فإن عجز يصوم شهرين متتابعين، فإن عجز يطعم ستين مسكينًا قبل أن يمسها، على الترتيب كما رتبها الله ، أولًا العتق إذا تيسر، فإن عجز يصوم شهرين متتابعين ستين يومًا، فإن عجز أطعم ستين مسكينًا ثلاثين صاعًا، كل فقير له نصف الصاع قبل أن يمسها. فإذا وطئها استعجل ووطئها وجبت عليه الكفارة وعليه التوبة إلى الله من ذلك؛ لأنه استعجل فعليه التوبة والندم خوفًا من الله  وتعظيمًا له، وتعينت عليه الكفارة حينئذ، إن كان مستطيعًا أعتق وإن كان لا يستطيع صام شهرين متتابعين ستين يومًا، وإن عجز أطعم ستين مسكينًا حتى ولو ماتت حتى ولو طلقها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16534/حكم-المساس-قبل-اداء-كفارة-الظهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84117.mp3","categories":["الطلاق","الظهار"]},{"id":18002,"question":"من المستمع محمد سليمان محمد بعث يسأل ويقول: إذا حلف الرجل على زوجته وقال لها: علي الحرام لا تصلي بيت فلان مثلًا: جارة أو ما أشبه ذلك، وبعد وقت وصلت الزوجة إلى ذلك البيت المحلوف عليه فما الحكم؟","title":"حكم الحلف بالحرام على الزوجة","answer":"الجواب: هذا فيه تفصيل: إن كان مقصوده تحريمها إذا فعلت ذلك فعليه كفارة الظهار في أصح أقوال أهل العلم وهي: عتق رقبة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا ثلاثين صاعًا لكل مسكين نصف صاع من قوت البلد قبل أن يمسها. أما إن كان المراد منعها وتحذيرها وتخويفها وتهديدها فهذا عليه كفارة يمين إذا خالفته، لا يلزمه كفارة الظهار ولكن كفارة اليمين؛ لأنه في حكم اليمين وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإن عجز صام ثلاثة أيام إذا كان مقصوده من هذا التحريم تخويفها وتحذيرها، مثلًا قال لها: عليه الحرام ما تكلمي فلان، عليه الحرام ما تعشين عند دار فلان، عليه الحرام ما تحضرين عرس آل فلان قصده منعها، فهكذا إذا قال: عليه الحرام ما تزورين آل فلان إذا كان المقصود التهديد والتخويف والتحذير وليس المقصود تحريمها عليه إن فعلت فإنه يكون فيه كفارة اليمين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17033/حكم-الحلف-بالحرام-على-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84917.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":18004,"question":"من المستمع محمد سليمان محمد بعث يسأل ويقول: إذا حلف الرجل على زوجته وقال لها: علي الحرام لا تصلي بيت فلان مثلًا: جارة أو ما أشبه ذلك، وبعد وقت وصلت الزوجة إلى ذلك البيت المحلوف عليه فما الحكم؟","title":"حكم الحلف بالحرام على الزوجة","answer":"الجواب: هذا فيه تفصيل: إن كان مقصوده تحريمها إذا فعلت ذلك فعليه كفارة الظهار في أصح أقوال أهل العلم وهي: عتق رقبة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا ثلاثين صاعًا لكل مسكين نصف صاع من قوت البلد قبل أن يمسها. أما إن كان المراد منعها وتحذيرها وتخويفها وتهديدها فهذا عليه كفارة يمين إذا خالفته، لا يلزمه كفارة الظهار ولكن كفارة اليمين؛ لأنه في حكم اليمين وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإن عجز صام ثلاثة أيام إذا كان مقصوده من هذا التحريم تخويفها وتحذيرها، مثلًا قال لها: عليه الحرام ما تكلمي فلان، عليه الحرام ما تعشين عند دار فلان، عليه الحرام ما تحضرين عرس آل فلان قصده منعها، فهكذا إذا قال: عليه الحرام ما تزورين آل فلان إذا كان المقصود التهديد والتخويف والتحذير وليس المقصود تحريمها عليه إن فعلت فإنه يكون فيه كفارة اليمين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17033/حكم-الحلف-بالحرام-على-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84917.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":18423,"question":"المستمع (م. م) من الدمام بعث برسالة يقول فيها: أعرض عليكم مشكلتي والتي تتلخص في أنني عزمت على ترك التدخين ولكن بدلًا من أؤكد كلامي على عزمي بذلك أمام السامع بالحلف بالله كما ينبغي أن يكون عليه المسلم أكدت بالحلف بالحرام، هل يقع الطلاق في هذه الحالة مع العلم أنني صمت ثلاثة أيام وعدت إلى فعل ما عزمت على ترك فعله على اعتقادي أن الحلف حلف يمين وليس بالطلاق، وإنما نطقت بالحرام للتأكيد للسامع فقط، هل يلزم كفارة في هذه الحالة؟","title":"أكدت الحلف بالحرام على ترك التدخين، هل يقع الطلاق؟","answer":"الجواب: نعم، إذا كنت قصدت منع نفسك من شرب الدخان بالتحريم أو باليمين أو بالطلاق، قلت: علي الحرام وعلي الطلاق أني ما أشرب هذا الدخان، أني لا أعود إليه، ومقصودك منع نفسك والتأكيد على نفسك، ليس قصدك تحريم زوجتك إن فعلت، وليس قصدك طلاقها إن فعلت وإنما أردت التأكيد على نفسك وإلزامها بالكف عن التدخين، فهذا حكمه حكم اليمين وعليك كفارتها وهي إطعام عشرة مساكين أو كسوتهم، ولا يجزئ الصيام إذا كنت قادر على الطعام أو الكسوة لا يجزئ الصيام؛ لأن الصيام إنما يجزئ مع العجز في حق من عجز عن الطعام أو الكسوة أو العتق، أما من قدر على واحد من الثلاثة، قدر على أن يطعم عشرة مساكين، أو يكسوهم، أو يعتق رقبة فإنه يلزمه واحد من هذه الثلاثة، فإن عجز عنها كلها صام ثلاثة أيام كما نص عليه القرآن الكريم في سورة المائدة. أما إن كنت أردت تحريم زوجتك إن فعلت أو أردت طلاقها إن فعلت فإنها تحرم عليك وعليك كفارة الظهار وهي عتق رقبة مع القدرة، فإن عجزت تصوم شهرين متتابعين ستين يومًا، فإن عجزت تطعم ستين مسكينًا ثلاثين صاعًا كل صاع بين اثنين من قوت البلد من تمر أو أرز أو غيرهما، كل صاع يكون بين اثنين، والصاع نحو ثلاثة كيلو تقريبًا. وهكذا إذا أردت الطلاق، إذا قلت: علي الطلاق وأردت طلاقها إن دخنت يكون طلقة واحدة، وعليك أن تراجعها إذا رجعت إلى التدخين إذا كنت لم تطلقها قبل هذا طلقتين فإنه يحل لك مراجعتها إذا كنت أردت إيقاع الطلاق، فتقول: اشهد يا فلان وفلان أني راجعت زوجتي، هذا هو السنة؛ تشهد اثنين أنك راجعت زوجتك بعد أن باشرت الدخان. والواجب عليك يا أخي تقوى الله، وأن تحذر التدخين لمضرته العظيمة وخبثه الكثير، والله سبحانه إنما أباح لعباده الطيبات، كما قال : يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4]، هكذا في سورة المائدة، وقال سبحانه في سورة الأعراف في وصف النبي عليه الصلاة والسلام قال: وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ [الأعراف:157]. ولا شك أن التدخين أمر منكر وأن الدخان من الخبائث، وقد قرر الأطباء العارفون به وكل من استعمله أنه مضر وخبيث، فعليك يا أخي أن تتقي الله وأن تحذر شر هذا البلاء، وأن تبتعد عنه، وأن تعزم عزمًا صادقًا عزم الرجال أن لا تعود إليه، رزقنا الله وإياك التوفيق والهداية.","link":"https://binbaz.org.sa/fatwas/17528/اكدت-الحلف-بالحرام-على-ترك-التدخين-هل-يقع-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_864/nour_86404.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":19124,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: (م.أ.م) المنياوي، أخونا له مجموعة من الأسئلة، في سؤاله الأول يقول: أنا متزوج، وفي مرة حدث خلاف بيننا، فقلت لها: أنت محرمة علي إن لم ترجعي عن الأمور التي تفعليها، وبعد أيام تصالحنا، وكان بيننا المعاشرة الزوجية، ثم سافرت إلى اليمن حيث أعمل.والآن ما هو موقفي بالنسبة لما صدر مني؟ هل تكون طلقة؟ أم يمين؟ وإذا كانت يمين فما هي الكفارة التي تكون علي؟ أسمع في الإجابة عن بعض الأسئلة والاستفسارات عن كفارتين: الأولى تقول: عتق رقبة، أو إطعام عشرة مساكين، أو صيام ثلاثة أيام، الثانية تقول: عتق رقبة، أو إطعام ستين مسكينًا، أو صيام ثلاثة أشهر، فما الفرق بين الكفارتين في الحكم الشرعي؟وهل من الممكن إخراج الكفارة على هيئة نقود توزع على الفقراء بما يساوي الإطعام؟جزاكم الله خيرًا.","title":"حكم قول الرجل لزوجته: أنت محرمة علي وما يترتب عليه","answer":"الجواب: هذا الكلام يحتاج إلى تفصيل حسب نية المتكلم، فإذا قال: هي محرمة عليه إذا لم تدع الأمور الفلانية، هذا إذا تركتها فلا تحريم، انتهى الأمر؛ لأنها امتثلت الأمر وتركت، فليس عليه شيء، أما إذا لم تترك بأن عاندت، وخالفت ولم تبالي بالكلام فهذا فيه تفصيل: إن كان أراد بهذا الكلام تحريمها أو تطليقها فهو على ما أراد، إن كان أراد التحريم فهي محرمة، وإن كان أراد الطلاق وقع الطلاق، وإن كان أراد منعها ولم يرد تحريمًا ولا طلاقًا وإنما أراد منعها والتشديد عليها وتخويفها وتحذيرها فهذا له حكم اليمين. فالمسألة تختلف بحسب النية، فإذا كان نوى بهذا الكلام تخويفها وتحذيرها ولكن لم تمتثل، فإن عليه كفارة يمين، وهي عتق رقبة مؤمنة، أو إطعام عشرة مساكين، أو كسوتهم، مخير بين الثلاث: عتق رقبة مؤمنة، أو إطعام عشرة مساكين، أو كسوتهم، والإطعام كونه يعشيهم أو يغديهم، أو يدفع إليهم نصف صاع لكل واحد، من التمر أو من الأرز من قوت البلد، يعني: كيلو ونصف تقريبًا، أو يكسوهم كسوة، كل واحد يعطيه إزار ورداء، أو قميص يستره في الصلاة، هذه هي الكفارة، فإن عجز عن هذا كله، عجز عن الإطعام وعن الكسوة وعن العتق، أجزأه أن يصوم ثلاثة أيام، عند العجز أن يصوم ثلاثة أيام، هذه كفارة اليمين. أما إن كان أراد تحريمها إذا لم تدع الأمور، أراد تحريمها فهذا حكمه حكم الظهار، كما لو قال: أنت علي كظهر أمي، أو ظهر أختي ونحو ذلك، فإذا حرمها بهذا التحريم، أو قال: أنت علي حرام أو محرمة إذا لم تدعي هذا الأمر، فلم تدعه قصده تحريمها فإن عليه كفارة الظهار: وهي عتق رقبة مؤمنة، فإن عجز فصيام شهرين متتابعين، فإن لم يستطع فإطعام ستين مسكينًا، وليس في الكفارة ثلاثة أشهر، ما فيها إلا شهران ما هي بثلاثة أشهر، الكفارة إما شهران وإما صيام ثلاثة أيام في كفارة اليمين، كما تقدم. والشهران في الظهار، يعني: تحريم الزوجة، وفي الوطء في رمضان، وفي قتل الخطأ وشبه العمد، أولاً: عتق رقبة مؤمنة، فإن عجز في تحريمه زوجته أو في وطئه في رمضان أو في قتله نفسًا بغير حق، إن عجز عن الرقبة صام شهرين متتابعين، ستين يومًا، فإن عجز بقيت الكفارة معلقة في ذمته حتى يستطيع إذا كان قتلًا، إذا كانت المعصية قتلًا، لأن الحادث قتلًا فليس فيه إطعام، بل تبقى الكفارة معلقة وهي عتق رقبة مؤمنة، فإن لم يستطع صام شهرين متتابعين، هذه كفارة القتل كما بينه الله في كتابه العظيم، فإذا عجز عن الصيام والعتق تبقى في ذمته متى قدر على العتق أعتق، ومتى استطاع الصيام صام. أما في الظهار، وتحريم الزوجة وفي الوطء في رمضان فهذا فيه أمر ثالث وهو الإطعام، عند العجز عن الرقبة وعند العجز عن الصيام يطعم ستين مسكينًا، ثلاثين صاعاً، في هاتين المسألتين: في مسألة الجماع في رمضان وفي مسألة تحريم الزوجة تحريمًا مطلقًا لا معلقًا بفعل كذا وفعل كذا، يقصد منعها، بل تحريم مطلق كأن يقول: أنت علي محرمة، أنت علي كظهر أمي، أو أنت علي محرمة إذا دخل رمضان، هذا هو التحريم المطلق، أو المعلق تعليقًا ليس فيه حث ولا منع، بل تعليقًا تامًا، فيترتب عليه حكم، فيلزم بعتق رقبة مؤمنة إذا قدر، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا، وفي الظهار قبل أن يمسها، في تحريم الزوجة يأتي بهذه الكفارة قبل أن يمسها، قبل أن يقربها، وهي مرتبة على هذا الترتيب: العتق ثم الصيام عند العجز عن العتق، ثم الإطعام عند العجز عن الصيام، والإطعام يكون لستين مسكينًا، طعامًا لا نقودًا، يطعمهم يعشيهم أو يغديهم أو يعطيهم على نصف صاع من التمر أو من الأرز أو من الحنطة حسب قوت البلد، ومقداره بالوزن نحو كيلو ونصف تقريبًا من جهة الوزن. وأما في التحريم المعلق تعليقًا مراد منه الحث أو المنع أو التصديق أو التكذيب هذا فيه كفارة اليمين كما تقدم، فإذا قال: أنت محرمة علي إن فعلت كذا، أو أنت طالق إن فعلت كذا، إن كلمت فلانًا، إن فعلت الأمر الفلاني، إن عصيت أمي، إن خرجت من البيت قصده تحذيرها، ليس قصده طلاقها، قصده تحذيرها وتخويفها فهذا حكم اليمين. وهكذا لو قال: أنت علي، أنت مطلقة إن فعلت كذا، قصده منعها، تحذيرها، وليس قصده فراقها، فهذا له حكم اليمين، في أصح قولي العلماء كما تقدم، والله ولي التوفيق. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18314/حكم-قول-الرجل-لزوجته-انت-محرمة-علي-وما-يترتب-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_885/nour_88506.mp3","categories":["الأيمان والنذور","الطلاق","الظهار"]},{"id":19143,"question":"مستمع بعث برسالة وآثر فيها عدم ذكر اسمه، يقول في أحد أسئلته: في ذات يوم تلفظت بلفظ الظهار، ولم يكن في نيتي الانفصال عن زوجتي، وكنت لا أعرف الفرق بين الظهار والطلاق، ثم إني فعلت الشيء الذي كان عليه الحلفان، فأطعمت عشرة مساكين، فهل هذا يكفي أم يقع علي حد الظهار؟ أفيدوني أفادكم الله وجزاكم الله خيرًا.","title":"حكم من ظاهر من زوجته جاهلًا بحكم الظهار","answer":"الجواب: إذا كنت ظاهرت من امرأتك قلت: علي زوجتي مثل ظهر أمي، أو مثل ظهر أختي فهذا الظهار ما يكفي عشرة مساكين لا بد من عتق رقبة مؤمنة، فإن عجزت فصيام شهرين متتابعين، فإن عجزت فإطعام ستين مسكينًا قبل أن تمسها؛ لكل مسكين نصف صاع يعني ثلاثين صاعًا. ونوصيك بمراجعة العلماء في بلدك القاضي، أو غيره من العلماء المعروفين بالعلم تسألهم عما جرى منك توضح لهم الواقع، إذا كنت ظاهرت من امرأتك يعني: قلت لها هي حرام عليك كأمك، أو كأختك، أو هي كظهر أمك، أو أختك، أو ما أشبه ذلك، فهذا كفارته مثلما بين الله في القرآن في سورة قد سمع، سورة المجادلة، كفارته مرتبة أولًا عتق رقبة مؤمنة إذا استطاع الإنسان، فإن عجز يصوم شهرين متتابعين ستين يومًا، فإن عجز يطعم ستين مسكين ثلاثين صاعًا لكل مسكين نصف صاع من قوت البلد مقداره كيلو ونص تقريبًا قبل أن يمس المرأة، وعليه التوبة من ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18323/حكم-من-ظاهر-من-زوجته-جاهلا-بحكم-الظهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_798/nour_79801.mp3","categories":["الطلاق","الظهار"]}]
